fn expr_type_layout<'a>(
    expr: &SpannedExpr,
    locals: Option<&HashMap<String, LocalInfo>>,
    st: &SymbolTable,
    type_layouts: &'a crate::sema::type_layout::TypeLayoutRegistry,
) -> Option<&'a crate::sema::type_layout::TypeLayout> {
    match operator_expr_type_info(expr, locals, st, Some(type_layouts)) {
        Some(crate::sema::symtab::TypeInfo::Derived(name))
        | Some(crate::sema::symtab::TypeInfo::Class(name)) => type_layouts.get(&name),
        _ => None,
    }
}

#[derive(Clone)]
enum ScalarAllocSourceCopyPlan {
    Static(String),
    Dynamic(String),
}

fn expr_scalar_alloc_source_copy_plan(
    expr: &SpannedExpr,
    locals: &HashMap<String, LocalInfo>,
    st: &SymbolTable,
    type_layouts: &crate::sema::type_layout::TypeLayoutRegistry,
) -> Option<ScalarAllocSourceCopyPlan> {
    if let Some(layout) = expr_type_layout(expr, Some(locals), st, type_layouts) {
        if !layout.is_abstract {
            return Some(ScalarAllocSourceCopyPlan::Static(layout.name.clone()));
        }
    }
    operator_expr_type_info(expr, Some(locals), st, Some(type_layouts))
        .and_then(|ti| abstract_layout_base_type(type_layouts, &ti))
        .map(ScalarAllocSourceCopyPlan::Dynamic)
}

fn expr_type_tag_value(
    b: &mut FuncBuilder,
    expr: &SpannedExpr,
    locals: Option<&HashMap<String, LocalInfo>>,
    st: &SymbolTable,
    type_layouts: &crate::sema::type_layout::TypeLayoutRegistry,
) -> Option<ValueId> {
    expr_type_layout(expr, locals, st, type_layouts)
        .map(|layout| b.const_i64(layout.type_tag as i64))
}

fn expr_tbp_lookup_value(
    b: &mut FuncBuilder,
    expr: &SpannedExpr,
    locals: Option<&HashMap<String, LocalInfo>>,
    st: &SymbolTable,
    type_layouts: &crate::sema::type_layout::TypeLayoutRegistry,
) -> Option<ValueId> {
    expr_type_layout(expr, locals, st, type_layouts)
        .and_then(|layout| type_layout_tbp_lookup_value(b, layout))
}

fn expr_derived_type_name(
    expr: &SpannedExpr,
    locals: Option<&HashMap<String, LocalInfo>>,
    st: &SymbolTable,
    type_layouts: &crate::sema::type_layout::TypeLayoutRegistry,
) -> Option<String> {
    expr_type_layout(expr, locals, st, type_layouts).map(|layout| layout.name.clone())
}

fn typed_allocate_type_tag_value(
    b: &mut FuncBuilder,
    type_spec: Option<&crate::ast::decl::TypeSpec>,
    type_layouts: &crate::sema::type_layout::TypeLayoutRegistry,
) -> Option<ValueId> {
    match type_spec {
        Some(crate::ast::decl::TypeSpec::Type(name))
        | Some(crate::ast::decl::TypeSpec::Class(name)) => type_layouts
            .get(name)
            .map(|layout| b.const_i64(layout.type_tag as i64)),
        _ => None,
    }
}

fn typed_allocate_tbp_lookup_value(
    b: &mut FuncBuilder,
    type_spec: Option<&crate::ast::decl::TypeSpec>,
    type_layouts: &crate::sema::type_layout::TypeLayoutRegistry,
) -> Option<ValueId> {
    match type_spec {
        Some(crate::ast::decl::TypeSpec::Type(name))
        | Some(crate::ast::decl::TypeSpec::Class(name)) => type_layouts
            .get(name)
            .and_then(|layout| type_layout_tbp_lookup_value(b, layout)),
        _ => None,
    }
}

fn emit_scalar_alloc_polymorphic_metadata_on_success(
    b: &mut FuncBuilder,
    stat_addr: ValueId,
    dest_desc: ValueId,
    tag_value: Option<ValueId>,
    lookup_ptr: Option<ValueId>,
) {
    if tag_value.is_none() && lookup_ptr.is_none() {
        return;
    }
    let stat = b.load_typed(stat_addr, IrType::Int(IntWidth::I32));
    let zero = b.const_i32(0);
    let ok = b.icmp(CmpOp::Eq, stat, zero);
    let set_bb = b.create_block("alloc_type_tag_set");
    let done_bb = b.create_block("alloc_type_tag_done");
    b.cond_branch(ok, set_bb, vec![], done_bb, vec![]);

    b.set_block(set_bb);
    if let Some(tag) = tag_value {
        store_array_desc_type_tag(b, dest_desc, tag);
    }
    if let Some(ptr) = lookup_ptr {
        store_array_desc_tbp_lookup_ptr(b, dest_desc, ptr);
    }
    b.branch(done_bb, vec![]);
    b.set_block(done_bb);
}

fn emit_scalar_alloc_source_descriptor_metadata_on_success(
    b: &mut FuncBuilder,
    stat_addr: ValueId,
    dest_desc: ValueId,
    source_desc: ValueId,
) {
    let stat = b.load_typed(stat_addr, IrType::Int(IntWidth::I32));
    let zero = b.const_i32(0);
    let ok = b.icmp(CmpOp::Eq, stat, zero);
    let set_bb = b.create_block("alloc_source_desc_meta_set");
    let done_bb = b.create_block("alloc_source_desc_meta_done");
    b.cond_branch(ok, set_bb, vec![], done_bb, vec![]);

    b.set_block(set_bb);
    let tag = load_array_desc_type_tag(b, source_desc);
    let lookup = load_array_desc_tbp_lookup_ptr(b, source_desc);
    store_array_desc_type_tag(b, dest_desc, tag);
    store_array_desc_tbp_lookup_ptr(b, dest_desc, lookup);
    b.branch(done_bb, vec![]);
    b.set_block(done_bb);
}

fn emit_scalar_allocate_source_init_on_success(
    b: &mut FuncBuilder,
    ctx: &LowerCtx,
    stat_addr: ValueId,
    dest_base: ValueId,
    dest_ty: &IrType,
    derived_type: Option<&str>,
    source_expr: &SpannedExpr,
) {
    let stat = b.load_typed(stat_addr, IrType::Int(IntWidth::I32));
    let zero = b.const_i32(0);
    let ok = b.icmp(CmpOp::Eq, stat, zero);
    let init_bb = b.create_block("alloc_source_init");
    let done_bb = b.create_block("alloc_source_init_done");
    b.cond_branch(ok, init_bb, vec![], done_bb, vec![]);

    b.set_block(init_bb);
    if let Some(type_name) = derived_type {
        let src = lower_expr_ctx_tl(b, ctx, source_expr);
        emit_derived_value_copy(b, ctx.type_layouts, type_name, dest_base, src);
    } else {
        let raw = lower_expr_ctx_tl(b, ctx, source_expr);
        let coerced = coerce_to_type(b, raw, dest_ty);
        b.store(coerced, dest_base);
    }
    b.branch(done_bb, vec![]);
    b.set_block(done_bb);
}

/// Resolve a base expression for a type-bound procedure call.
/// Returns (object_address, type_name) — the address of the base object.
/// For simple `obj%method()`, base is `obj` → returns (obj.addr, obj.type).
/// For `obj%inner%method()`, base is `obj%inner` → returns (inner.addr, inner.type).
fn resolve_component_base_for_method(
    b: &mut FuncBuilder,
    locals: &HashMap<String, LocalInfo>,
    base: &crate::ast::expr::SpannedExpr,
    st: &SymbolTable,
    tl: &crate::sema::type_layout::TypeLayoutRegistry,
) -> Option<(ValueId, String)> {
    match &base.node {
        Expr::Name { name } => {
            let key = name.to_lowercase();
            let info = locals.get(&key)?;
            let type_name = info.derived_type.as_ref()?.clone();
            let addr = if info.is_pointer && local_uses_array_descriptor(info) && info.dims.is_empty()
            {
                array_base_addr(b, info)
            } else if info.is_pointer {
                b.load_typed(info.addr, IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))))
            } else if info.allocatable {
                array_base_addr(b, info)
            } else if info.by_ref {
                b.load(info.addr)
            } else {
                info.addr
            };
            Some((addr, type_name))
        }
        Expr::ComponentAccess {
            base: inner_base,
            component,
        } => {
            // Resolve the inner base, then GEP to the component field.
            let (inner_addr, inner_type) =
                resolve_component_base_for_method(b, locals, inner_base, st, tl)?;
            let layout = tl.get(&inner_type)?;
            let field = layout.field(component)?;
            let offset = b.const_i64(field.offset as i64);
            let field_ptr = b.gep(inner_addr, vec![offset], IrType::Int(IntWidth::I8));
            if let crate::sema::symtab::TypeInfo::Derived(ref nested_type) = field.type_info {
                if is_opaque_c_handle_type(&field.type_info) {
                    return None;
                }
                let addr = if field.size == 384 && (field.allocatable || field.pointer) {
                    b.load_typed(field_ptr, IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))))
                } else {
                    field_ptr
                };
                Some((addr, nested_type.clone()))
            } else {
                None
            }
        }
        Expr::FunctionCall { callee, args } => {
            if args
                .iter()
                .any(|arg| !matches!(arg.value, crate::ast::expr::SectionSubscript::Element(_)))
            {
                return None;
            }
            if let Expr::Name { name } = &callee.node {
                let info = locals.get(&name.to_lowercase())?;
                let type_name = info.derived_type.as_ref()?.clone();
                if info.dims.is_empty() && !local_uses_array_descriptor(info) {
                    return None;
                }
                let elem_addr = lower_array_element(b, locals, info, args, st, Some(tl));
                return Some((elem_addr, type_name));
            }
            if let Expr::ComponentAccess { .. } = &callee.node {
                if let Some(info) = component_array_local_info(b, locals, callee, st, tl) {
                    let type_name = info.derived_type.as_ref()?.clone();
                    let elem_addr = lower_array_element(b, locals, &info, args, st, Some(tl));
                    return Some((elem_addr, type_name));
                }
                let (field_ptr, field) = resolve_component_field_access(b, locals, callee, st, tl)?;
                let crate::sema::symtab::TypeInfo::Derived(type_name) = &field.type_info else {
                    return None;
                };
                let layout = tl.get(type_name)?;
                let elem_addr = lower_fixed_component_array_element_ptr(
                    b,
                    locals,
                    args,
                    st,
                    tl,
                    field_ptr,
                    &field.dims,
                    layout.size as i64,
                )?;
                return Some((elem_addr, type_name.clone()));
            }
            None
        }
        _ => None,
    }
}

enum MethodBaseKind {
    Derived(String),
    PolymorphicClass(String),
}

fn method_base_kind_for_call(
    base: &crate::ast::expr::SpannedExpr,
    locals: &HashMap<String, LocalInfo>,
    st: &SymbolTable,
    tl: &crate::sema::type_layout::TypeLayoutRegistry,
) -> Option<MethodBaseKind> {
    match operator_expr_type_info(base, Some(locals), st, Some(tl))? {
        crate::sema::symtab::TypeInfo::Derived(name) => Some(MethodBaseKind::Derived(name)),
        crate::sema::symtab::TypeInfo::Class(name) => Some(MethodBaseKind::PolymorphicClass(name)),
        _ => None,
    }
}

fn reject_unsupported_polymorphic_component_method_base(
    span: crate::lexer::Span,
    base: &crate::ast::expr::SpannedExpr,
    locals: &HashMap<String, LocalInfo>,
    st: &SymbolTable,
    tl: &crate::sema::type_layout::TypeLayoutRegistry,
) {
    if matches!(
        method_base_kind_for_call(base, locals, st, tl),
        Some(MethodBaseKind::PolymorphicClass(_))
    ) {
        eprintln!(
            "armfortas: error: {}:{}: type-bound calls through CLASS(...) component bases are not implemented yet",
            span.start.line, span.start.col
        );
        let _ = std::io::stderr().flush();
        std::process::exit(1);
    }
}

fn lower_char_arg_by_ref(
    b: &mut FuncBuilder,
    locals: &HashMap<String, LocalInfo>,
    expr: &crate::ast::expr::SpannedExpr,
    st: &SymbolTable,
    type_layouts: Option<&crate::sema::type_layout::TypeLayoutRegistry>,
    internal_funcs: Option<&HashMap<String, u32>>,
    contained_host_refs: Option<&HashMap<String, Vec<String>>>,
    descriptor_params: Option<&HashMap<String, Vec<bool>>>,
) -> Option<ValueId> {
    use crate::ast::expr::Expr;

    match &expr.node {
        Expr::Name { name } => {
            let info = locals.get(&name.to_lowercase())?;
            if !info.dims.is_empty() {
                return None;
            }
            if info.by_ref {
                match info.char_kind {
                    CharKind::Fixed(_)
                    | CharKind::FixedRuntime { .. }
                    | CharKind::AssumedLen { .. } => {
                        return Some(b.load(info.addr));
                    }
                    _ => {}
                }
            }
            if info.by_ref
                && info.derived_type.is_none()
                && info.char_kind == CharKind::None
                && matches!(
                    info.ty,
                    IrType::Ptr(ref inner) if matches!(inner.as_ref(), IrType::Int(IntWidth::I8))
                )
            {
                return Some(info.addr);
            }
            let (ptr, _len) = char_addr_and_runtime_len(b, expr, locals)?;
            let slot = b.alloca(IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))));
            b.store(ptr, slot);
            Some(slot)
        }
        Expr::ComponentAccess { .. } => {
            let tl = type_layouts?;
            let (field_ptr, field) = resolve_component_field_access(b, locals, expr, st, tl)?;
            match field_char_kind(&field) {
                CharKind::Fixed(_) => {
                    let slot = b.alloca(IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))));
                    b.store(field_ptr, slot);
                    Some(slot)
                }
                CharKind::Deferred if field.size == 32 => {
                    let (ptr, _len) = load_string_descriptor_view(b, field_ptr);
                    let slot = b.alloca(IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))));
                    b.store(ptr, slot);
                    Some(slot)
                }
                _ => None,
            }
        }
        Expr::StringLiteral { value, .. } => {
            let src = b.const_string(value.as_bytes());
            let buf = b.alloca(IrType::Array(
                Box::new(IrType::Int(IntWidth::I8)),
                (value.len() + 1) as u64,
            ));
            let zero = b.const_i32(0);
            let total = b.const_i64((value.len() + 1) as i64);
            b.call(
                FuncRef::External("memset".into()),
                vec![buf, zero, total],
                IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))),
            );
            let len = b.const_i64(value.len() as i64);
            b.call(
                FuncRef::External("memcpy".into()),
                vec![buf, src, len],
                IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))),
            );
            let zero_idx = b.const_i64(0);
            let ptr = b.gep(buf, vec![zero_idx], IrType::Int(IntWidth::I8));
            let slot = b.alloca(IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))));
            b.store(ptr, slot);
            Some(slot)
        }
        Expr::FunctionCall { callee, args } => {
            let Expr::Name { name } = &callee.node else {
                if let Expr::ComponentAccess { .. } = &callee.node {
                    let tl = type_layouts?;
                    if let Some((ptr, _len)) =
                        fixed_component_char_array_elem_ptr_and_len(b, locals, callee, args, st, tl)
                    {
                        let slot = b.alloca(IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))));
                        b.store(ptr, slot);
                        return Some(slot);
                    }
                    let info = component_intrinsic_local_info(b, locals, callee, st, tl)?;
                    if info.char_kind == CharKind::None
                        && !descriptor_backed_runtime_char_array(&info)
                    {
                        return None;
                    }
                    let ptr = if local_uses_array_descriptor(&info)
                        || inline_char_array_storage(&info)
                    {
                        char_array_element_ptr_and_len(b, locals, &info, args, st, type_layouts)?.0
                    } else {
                        lower_array_element(b, locals, &info, args, st, type_layouts)
                    };
                    let slot = b.alloca(IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))));
                    b.store(ptr, slot);
                    return Some(slot);
                }
                return None;
            };
            let info = locals.get(&name.to_lowercase())?;
            if info.char_kind != CharKind::None && info.dims.is_empty() {
                let (ptr, _len) = lower_string_expr_full(
                    b,
                    locals,
                    expr,
                    st,
                    type_layouts,
                    internal_funcs,
                    contained_host_refs,
                    descriptor_params,
                );
                let slot = b.alloca(IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))));
                b.store(ptr, slot);
                return Some(slot);
            }
            if (info.char_kind == CharKind::None && !descriptor_backed_runtime_char_array(info))
                || (info.dims.is_empty() && !local_uses_array_descriptor(info))
            {
                return None;
            }
            let ptr = if local_uses_array_descriptor(info) || inline_char_array_storage(info) {
                char_array_element_ptr_and_len(b, locals, info, args, st, type_layouts)?.0
            } else {
                lower_array_element(b, locals, info, args, st, type_layouts)
            };
            let slot = b.alloca(IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))));
            b.store(ptr, slot);
            Some(slot)
        }
        _ => None,
    }
}

fn lower_arg_string_descriptor(
    b: &mut FuncBuilder,
    locals: &HashMap<String, LocalInfo>,
    expr: &crate::ast::expr::SpannedExpr,
    st: &SymbolTable,
    type_layouts: Option<&crate::sema::type_layout::TypeLayoutRegistry>,
) -> ValueId {
    match &expr.node {
        Expr::ParenExpr { inner } => {
            lower_arg_string_descriptor(b, locals, inner, st, type_layouts)
        }
        Expr::Name { name } => {
            let key = name.to_lowercase();
            if let Some(info) = locals.get(&key) {
                if matches!(info.char_kind, CharKind::Deferred) {
                    return string_descriptor_addr(b, info);
                }
            }
            b.const_i64(0)
        }
        Expr::ComponentAccess { .. } => {
            if let Some(tl) = type_layouts {
                if let Some((field_ptr, field)) =
                    resolve_component_field_access(b, locals, expr, st, tl)
                {
                    if matches!(field_char_kind(&field), CharKind::Deferred) && field.size == 32 {
                        return field_ptr;
                    }
                }
            }
            b.const_i64(0)
        }
        _ => b.const_i64(0),
    }
}

fn lower_arg_by_ref_full(
    b: &mut FuncBuilder,
    locals: &HashMap<String, LocalInfo>,
    expr: &crate::ast::expr::SpannedExpr,
    st: &SymbolTable,
    type_layouts: Option<&crate::sema::type_layout::TypeLayoutRegistry>,
    internal_funcs: Option<&HashMap<String, u32>>,
    contained_host_refs: Option<&HashMap<String, Vec<String>>>,
    descriptor_params: Option<&HashMap<String, Vec<bool>>>,
) -> ValueId {
    if let Some(ptr_slot) = lower_char_arg_by_ref(
        b,
        locals,
        expr,
        st,
        type_layouts,
        internal_funcs,
        contained_host_refs,
        descriptor_params,
    ) {
        return ptr_slot;
    }
    if expr_is_character_expr(b, locals, expr, st, type_layouts)
        && !expr_is_array_designator(b, locals, expr, st, type_layouts)
    {
        let (ptr, _len) = lower_string_expr_full(
            b,
            locals,
            expr,
            st,
            type_layouts,
            internal_funcs,
            contained_host_refs,
            descriptor_params,
        );
        let slot = b.alloca(IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))));
        b.store(ptr, slot);
        return slot;
    }
    // If it's a simple name, pass its address.
    if let Expr::Name { name } = &expr.node {
        let key = name.to_lowercase();
        if let Some(info) = locals.get(&key) {
            if let Some(c) = info.inline_const {
                let val = materialize_const_scalar(b, c, &info.ty);
                let tmp = b.alloca(info.ty.clone());
                b.store(val, tmp);
                return tmp;
            }
            if info.is_pointer && !info.by_ref && info.dims.is_empty() {
                let load_ty = if info.ty.is_ptr() {
                    info.ty.clone()
                } else {
                    IrType::Ptr(Box::new(info.ty.clone()))
                };
                return b.load_typed(info.addr, load_ty);
            }
            if info.derived_type.is_some() && info.dims.is_empty() && !info.is_pointer {
                return derived_scalar_storage_addr_for_call(b, info);
            }
            if info.by_ref {
                if info.descriptor_arg {
                    return array_data_ptr_for_call(b, info);
                }
                // Already a pointer to caller's storage — load and pass it.
                return b.load(info.addr);
            }
            if !info.dims.is_empty() || local_uses_array_descriptor(info) {
                return array_data_ptr_for_call(b, info);
            }
            return info.addr;
        }
        if let Some(sym) = find_linkable_symbol_any_scope(st, &key) {
            if matches!(
                sym.kind,
                crate::sema::symtab::SymbolKind::Function
                    | crate::sema::symtab::SymbolKind::Subroutine
                    | crate::sema::symtab::SymbolKind::ExternalProc
            ) {
                let (link_name, resolved_key) = resolved_symbol_call_target(st, &key, name);
                if let Some(internal_funcs) = internal_funcs {
                    if internal_funcs.contains_key(&resolved_key)
                        || internal_funcs.contains_key(&key)
                    {
                        let lowered = lowered_procedure_symbol_name(
                            resolved_key.as_str(),
                            None,
                            Some(b.func().name.as_str()),
                            None,
                            true,
                            internal_funcs,
                        );
                        return b.global_addr(&lowered, IrType::Int(IntWidth::I8));
                    }
                }
                return b.global_addr(&link_name, IrType::Int(IntWidth::I8));
            }
        }
    }
    if let Expr::ComponentAccess { .. } = &expr.node {
        if let Some(tl) = type_layouts {
            if let Some((field_ptr, field)) =
                resolve_component_field_access(b, locals, expr, st, tl)
            {
                if matches!(field.type_info, crate::sema::symtab::TypeInfo::Derived(_))
                    && !is_opaque_c_handle_type(&field.type_info)
                    && field.dims.is_empty()
                    && !field.pointer
                {
                    let info = LocalInfo {
                        addr: field_ptr,
                        ty: field_storage_ir_type(&field, tl),
                        dims: field.dims.clone(),
                        allocatable: field.allocatable,
                        descriptor_arg: field_uses_array_descriptor(&field),
                        by_ref: false,
                        char_kind: field_char_kind(&field),
                        derived_type: field_derived_type_name(&field),
                        inline_const: None,
                        is_pointer: false,
                        runtime_dim_upper: vec![],
                        is_class: false,
                    };
                    return derived_scalar_storage_addr_for_call(b, &info);
                }
                if field.pointer {
                    if is_deferred_char_component_field(&field) {
                        return field_ptr;
                    }
                    if field.size == 384 && (field.allocatable || field.pointer) {
                        return field_ptr;
                    }
                    if matches!(field.type_info, crate::sema::symtab::TypeInfo::Derived(_)) {
                        return b.load_typed(
                            field_ptr,
                            IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))),
                        );
                    }
                    let pointee_ty = type_info_to_ir_type(&field.type_info);
                    let slot_ty = IrType::Ptr(Box::new(pointee_ty));
                    return b.load_typed(field_ptr, slot_ty);
                }
                let _ = field;
                // Component actuals like `state%num_tokens` are lvalues:
                // pass the field storage itself so intent(out/inout)
                // dummies update the parent object rather than a temp.
                return field_ptr;
            }
        }
    }
    // Array element: arr(i) passed by ref should pass the address
    // of the element within arr, NOT a copy.  This enables sequence
    // association (F2018 §15.5.2.11): a callee that declares a
    // larger dummy can walk to successive elements from the passed
    // address.
    if let Expr::FunctionCall { callee, args } = &expr.node {
        if let Expr::Name { name } = &callee.node {
            let key = name.to_lowercase();
            if let Some(info) = locals.get(&key) {
                if (!info.dims.is_empty() || local_uses_array_descriptor(info))
                    && args.iter().all(|arg| {
                        matches!(arg.value, crate::ast::expr::SectionSubscript::Element(_))
                    })
                {
                    let elem = lower_array_element_addr(b, locals, info, args, st, type_layouts);
                    if info.derived_type.is_some() {
                        let zero = b.const_i64(0);
                        return b.gep(elem, vec![zero], IrType::Int(IntWidth::I8));
                    }
                    return elem;
                }
            }
        }
        if let Expr::ComponentAccess { .. } = &callee.node {
            if let Some(tl) = type_layouts {
                if let Some(info) = component_intrinsic_local_info(b, locals, callee, st, tl) {
                    if !info.dims.is_empty() || local_uses_array_descriptor(&info) {
                        let elem = lower_array_element_addr(b, locals, &info, args, st, Some(tl));
                        if info.derived_type.is_some() {
                            let zero = b.const_i64(0);
                            return b.gep(elem, vec![zero], IrType::Int(IntWidth::I8));
                        }
                        return elem;
                    }
                }
            }
        }
    }
    // Otherwise, evaluate and store to a temp.
    let val = lower_expr_full(
        b,
        locals,
        expr,
        st,
        type_layouts,
        internal_funcs,
        contained_host_refs,
        descriptor_params,
    );
    let ty = b
        .func()
        .value_type(val)
        .unwrap_or(IrType::Int(IntWidth::I32));
    if ty.is_ptr() {
        return val;
    }
    let tmp = b.alloca(ty);
    b.store(val, tmp);
    tmp
}

fn lower_bind_c_char_arg_raw(
    b: &mut FuncBuilder,
    locals: &HashMap<String, LocalInfo>,
    expr: &crate::ast::expr::SpannedExpr,
    st: &SymbolTable,
    type_layouts: Option<&crate::sema::type_layout::TypeLayoutRegistry>,
    internal_funcs: Option<&HashMap<String, u32>>,
    contained_host_refs: Option<&HashMap<String, Vec<String>>>,
    descriptor_params: Option<&HashMap<String, Vec<bool>>>,
) -> ValueId {
    use crate::ast::expr::Expr;

    if let Expr::Name { name } = &expr.node {
        if let Some(info) = locals.get(&name.to_lowercase()) {
            if !info.dims.is_empty() || local_uses_array_descriptor(info) {
                return array_data_ptr_for_call(b, info);
            }
            if let Some((ptr, _len)) = local_char_ptr_and_len(b, info) {
                return ptr;
            }
        }
    }

    if let Expr::ComponentAccess { .. } = &expr.node {
        if let Some(tl) = type_layouts {
            if let Some((field_ptr, field)) =
                resolve_component_field_access(b, locals, expr, st, tl)
            {
                return match field_char_kind(&field) {
                    CharKind::Fixed(_) => field_ptr,
                    CharKind::Deferred if field.size == 32 => {
                        load_string_descriptor_view(b, field_ptr).0
                    }
                    _ => field_ptr,
                };
            }
        }
    }

    if let Some((ptr, _len)) = char_addr_and_runtime_len(b, expr, locals) {
        return ptr;
    }

    if expr_is_character_expr(b, locals, expr, st, type_layouts) {
        return lower_string_expr_full(
            b,
            locals,
            expr,
            st,
            type_layouts,
            internal_funcs,
            contained_host_refs,
            descriptor_params,
        )
        .0;
    }

    lower_arg_by_ref_full(
        b,
        locals,
        expr,
        st,
        type_layouts,
        internal_funcs,
        contained_host_refs,
        descriptor_params,
    )
}

fn lower_bind_c_char_value_arg(
    b: &mut FuncBuilder,
    locals: &HashMap<String, LocalInfo>,
    expr: &crate::ast::expr::SpannedExpr,
    st: &SymbolTable,
    type_layouts: Option<&crate::sema::type_layout::TypeLayoutRegistry>,
    internal_funcs: Option<&HashMap<String, u32>>,
    contained_host_refs: Option<&HashMap<String, Vec<String>>>,
    descriptor_params: Option<&HashMap<String, Vec<bool>>>,
) -> ValueId {
    let ptr = lower_bind_c_char_arg_raw(
        b,
        locals,
        expr,
        st,
        type_layouts,
        internal_funcs,
        contained_host_refs,
        descriptor_params,
    );
    b.load_typed(ptr, IrType::Int(IntWidth::I8))
}

fn lower_arg_by_ref(
    b: &mut FuncBuilder,
    locals: &HashMap<String, LocalInfo>,
    expr: &crate::ast::expr::SpannedExpr,
    st: &SymbolTable,
) -> ValueId {
    lower_arg_by_ref_full(b, locals, expr, st, None, None, None, None)
}

fn lower_arg_by_ref_ctx(
    b: &mut FuncBuilder,
    ctx: &LowerCtx,
    expr: &crate::ast::expr::SpannedExpr,
) -> ValueId {
    lower_arg_by_ref_full(
        b,
        &ctx.locals,
        expr,
        ctx.st,
        Some(ctx.type_layouts),
        Some(ctx.internal_funcs),
        Some(ctx.contained_host_refs),
        Some(ctx.descriptor_params),
    )
}

fn lower_pointer_dummy_actual(
    b: &mut FuncBuilder,
    locals: &HashMap<String, LocalInfo>,
    expr: &crate::ast::expr::SpannedExpr,
    st: &SymbolTable,
    type_layouts: Option<&crate::sema::type_layout::TypeLayoutRegistry>,
    internal_funcs: Option<&HashMap<String, u32>>,
    contained_host_refs: Option<&HashMap<String, Vec<String>>>,
    descriptor_params: Option<&HashMap<String, Vec<bool>>>,
) -> Option<ValueId> {
    if let Expr::Name { name } = &expr.node {
        let info = locals.get(&name.to_lowercase())?;
        if !info.is_pointer {
            return None;
        }
        return Some(if info.by_ref {
            b.load(info.addr)
        } else {
            info.addr
        });
    }
    if let Expr::ComponentAccess { .. } = &expr.node {
        let tl = type_layouts?;
        let (field_ptr, field) = resolve_component_field_access(b, locals, expr, st, tl)?;
        if field.pointer {
            return Some(field_ptr);
        }
    }
    if let Expr::FunctionCall { callee, args } = &expr.node {
        if args
            .iter()
            .any(|arg| !matches!(arg.value, crate::ast::expr::SectionSubscript::Element(_)))
        {
            let raw = lower_expr_full(
                b,
                locals,
                expr,
                st,
                type_layouts,
                internal_funcs,
                contained_host_refs,
                descriptor_params,
            );
            if !b.func().value_type(raw).is_some_and(|ty| ty.is_ptr()) {
                return None;
            }
            let slot = b.alloca(IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))));
            let ptr = coerce_to_type(b, raw, &IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))));
            b.store(ptr, slot);
            return Some(slot);
        }
        if let Expr::Name { name } = &callee.node {
            if let Some(info) = locals.get(&name.to_lowercase()) {
                if !info.dims.is_empty() || local_uses_array_descriptor(info) {
                    let elem_addr =
                        lower_array_element_addr(b, locals, info, args, st, type_layouts);
                    let slot = b.alloca(IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))));
                    b.store(elem_addr, slot);
                    return Some(slot);
                }
            }
        }
        if let Expr::ComponentAccess { .. } = &callee.node {
            let tl = type_layouts?;
            if let Some(info) = component_array_local_info(b, locals, callee, st, tl) {
                let elem_addr = lower_array_element_addr(b, locals, &info, args, st, type_layouts);
                let slot = b.alloca(IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))));
                b.store(elem_addr, slot);
                return Some(slot);
            }
        }
    }

    let raw = lower_expr_full(
        b,
        locals,
        expr,
        st,
        type_layouts,
        internal_funcs,
        contained_host_refs,
        descriptor_params,
    );
    if !b.func().value_type(raw).is_some_and(|ty| ty.is_ptr()) {
        return None;
    }
    let slot = b.alloca(IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))));
    let ptr = coerce_to_type(b, raw, &IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))));
    b.store(ptr, slot);
    Some(slot)
}

/// Lower an expression to a ValueId.
fn lower_expr(
    b: &mut FuncBuilder,
    locals: &HashMap<String, LocalInfo>,
    expr: &crate::ast::expr::SpannedExpr,
    st: &SymbolTable,
) -> ValueId {
    lower_expr_full(b, locals, expr, st, None, None, None, None)
}

fn lower_expr_with_optional_layouts(
    b: &mut FuncBuilder,
    locals: &HashMap<String, LocalInfo>,
    expr: &crate::ast::expr::SpannedExpr,
    st: &SymbolTable,
    type_layouts: Option<&crate::sema::type_layout::TypeLayoutRegistry>,
) -> ValueId {
    if let Some(tl) = type_layouts {
        lower_expr_tl(b, locals, expr, st, tl)
    } else {
        lower_expr(b, locals, expr, st)
    }
}

fn lower_expr_ctx(
    b: &mut FuncBuilder,
    ctx: &LowerCtx,
    expr: &crate::ast::expr::SpannedExpr,
) -> ValueId {
    lower_expr_full(
        b,
        &ctx.locals,
        expr,
        ctx.st,
        Some(ctx.type_layouts),
        Some(ctx.internal_funcs),
        Some(ctx.contained_host_refs),
        Some(ctx.descriptor_params),
    )
}

fn lower_expr_tl(
    b: &mut FuncBuilder,
    locals: &HashMap<String, LocalInfo>,
    expr: &crate::ast::expr::SpannedExpr,
    st: &SymbolTable,
    tl: &crate::sema::type_layout::TypeLayoutRegistry,
) -> ValueId {
    lower_expr_full(b, locals, expr, st, Some(tl), None, None, None)
}

fn lower_expr_ctx_tl(
    b: &mut FuncBuilder,
    ctx: &LowerCtx,
    expr: &crate::ast::expr::SpannedExpr,
) -> ValueId {
    lower_expr_full(
        b,
        &ctx.locals,
        expr,
        ctx.st,
        Some(ctx.type_layouts),
        Some(ctx.internal_funcs),
        Some(ctx.contained_host_refs),
        Some(ctx.descriptor_params),
    )
}

fn lower_short_circuit_logical_expr(
    b: &mut FuncBuilder,
    locals: &HashMap<String, LocalInfo>,
    expr: &crate::ast::expr::SpannedExpr,
    st: &SymbolTable,
    type_layouts: Option<&crate::sema::type_layout::TypeLayoutRegistry>,
    internal_funcs: Option<&HashMap<String, u32>>,
    contained_host_refs: Option<&HashMap<String, Vec<String>>>,
    descriptor_params: Option<&HashMap<String, Vec<bool>>>,
) -> ValueId {
    match &expr.node {
        Expr::ParenExpr { inner } => lower_short_circuit_logical_expr(
            b,
            locals,
            inner,
            st,
            type_layouts,
            internal_funcs,
            contained_host_refs,
            descriptor_params,
        ),
        Expr::BinaryOp {
            op: BinaryOp::And,
            left,
            right,
        } => {
            let lhs = lower_short_circuit_logical_expr(
                b,
                locals,
                left,
                st,
                type_layouts,
                internal_funcs,
                contained_host_refs,
                descriptor_params,
            );
            let bb_rhs = b.create_block("and_rhs_expr");
            let bb_false = b.create_block("and_false_expr");
            let bb_merge = b.create_block("and_merge_expr");
            let result = b.add_block_param(bb_merge, IrType::Bool);
            b.cond_branch(lhs, bb_rhs, vec![], bb_false, vec![]);

            b.set_block(bb_rhs);
            let rhs = lower_short_circuit_logical_expr(
                b,
                locals,
                right,
                st,
                type_layouts,
                internal_funcs,
                contained_host_refs,
                descriptor_params,
            );
            b.branch(bb_merge, vec![rhs]);

            b.set_block(bb_false);
            let false_val = b.const_bool(false);
            b.branch(bb_merge, vec![false_val]);

            b.set_block(bb_merge);
            result
        }
        Expr::BinaryOp {
            op: BinaryOp::Or,
            left,
            right,
        } => {
            let lhs = lower_short_circuit_logical_expr(
                b,
                locals,
                left,
                st,
                type_layouts,
                internal_funcs,
                contained_host_refs,
                descriptor_params,
            );
            let bb_true = b.create_block("or_true_expr");
            let bb_rhs = b.create_block("or_rhs_expr");
            let bb_merge = b.create_block("or_merge_expr");
            let result = b.add_block_param(bb_merge, IrType::Bool);
            b.cond_branch(lhs, bb_true, vec![], bb_rhs, vec![]);

            b.set_block(bb_true);
            let true_val = b.const_bool(true);
            b.branch(bb_merge, vec![true_val]);

            b.set_block(bb_rhs);
            let rhs = lower_short_circuit_logical_expr(
                b,
                locals,
                right,
                st,
                type_layouts,
                internal_funcs,
                contained_host_refs,
                descriptor_params,
            );
            b.branch(bb_merge, vec![rhs]);

            b.set_block(bb_merge);
            result
        }
        _ => {
            let raw = lower_expr_full(
                b,
                locals,
                expr,
                st,
                type_layouts,
                internal_funcs,
                contained_host_refs,
                descriptor_params,
            );
            coerce_to_type(b, raw, &IrType::Bool)
        }
    }
}

fn lower_expr_full(
    b: &mut FuncBuilder,
    locals: &HashMap<String, LocalInfo>,
    expr: &crate::ast::expr::SpannedExpr,
    st: &SymbolTable,
    type_layouts: Option<&crate::sema::type_layout::TypeLayoutRegistry>,
    internal_funcs: Option<&HashMap<String, u32>>,
    contained_host_refs: Option<&HashMap<String, Vec<String>>>,
    descriptor_params: Option<&HashMap<String, Vec<bool>>>,
) -> ValueId {
    match &expr.node {
        Expr::IntegerLiteral { text, kind, .. } => {
            let clean = text.split('_').next().unwrap_or(text);
            let kind_width = kind
                .as_deref()
                .map(|kind_str| int_kind_to_width_in_context(kind_str, Some(locals), None, Some(st)))
                .unwrap_or_else(crate::driver::defaults::default_int_kind);
            let val: i128 = clean.parse().unwrap_or(0);
            let width = match kind_width {
                0..=1 => IntWidth::I8,
                2 => IntWidth::I16,
                3..=4 => IntWidth::I32,
                5..=8 => IntWidth::I64,
                _ => IntWidth::I128,
            };
            b.const_int(val, width)
        }
        Expr::RealLiteral { text, kind } => {
            let val: f64 = text
                .replace('d', "e")
                .replace('D', "E")
                .parse()
                .unwrap_or(0.0);
            // Determine width from kind suffix (_dp, _8), 'd' exponent, or default.
            let is_f64 = if let Some(kind_str) = kind {
                real_kind_to_width_in_context(kind_str, Some(locals), None, Some(st)) == 8
            } else {
                text.to_lowercase().contains('d')
            };
            if is_f64 {
                b.const_f64(val)
            } else {
                b.const_f32(val as f32)
            }
        }
        Expr::LogicalLiteral { value, .. } => b.const_bool(*value),
        Expr::StringLiteral { value, .. } => b.const_string(value.as_bytes()),
        Expr::BozLiteral { text, base } => {
            // BOZ literals: strip prefix letter and quotes, parse digit string.
            let radix = match base {
                crate::ast::expr::BozBase::Binary => 2,
                crate::ast::expr::BozBase::Octal => 8,
                crate::ast::expr::BozBase::Hex => 16,
            };
            // Token text is like Z'FF' or B'1010' — extract the digits between quotes.
            let digits: String = text
                .chars()
                .skip_while(|c| !matches!(c, '\'' | '"'))
                .skip(1) // skip opening quote
                .take_while(|c| !matches!(c, '\'' | '"'))
                .collect();
            let val = i64::from_str_radix(&digits, radix).unwrap_or(0);
            if val > i32::MAX as i64 || val < i32::MIN as i64 {
                b.const_i64(val)
            } else {
                b.const_i32(val as i32)
            }
        }

        Expr::Name { name } => {
            let key = name.to_lowercase();
            if let Some(info) = locals.get(&key) {
                // Audit MAJOR-4: PARAMETER-attributed locals with
                // a folded value get inlined directly. The const
                // is materialized via the appropriate b.const_*
                // helper, matching the local's declared type.
                if let Some(c) = info.inline_const {
                    return materialize_const_scalar(b, c, &info.ty);
                }
                if !info.dims.is_empty() {
                    // Array name without subscripts — return the base address.
                    info.addr
                } else if info.is_pointer && is_complex_ty(&info.ty) {
                    // Complex POINTER: slot holds ptr<[f32/f64 x 2]>.
                    // Consumers of complex values want the *address* of
                    // the 2-element buffer (same ABI as an ordinary
                    // complex variable), so load once to get the
                    // associated buffer and return that.
                    b.load_typed(info.addr, IrType::Ptr(Box::new(info.ty.clone())))
                } else if info.is_pointer && info.derived_type.is_none() {
                    // Scalar Fortran POINTER: `info.addr` is an alloca
                    // ptr<T>.  Reading the pointer as a value
                    // dereferences it: load the target address out of
                    // the slot, then load the value through it.
                    let tgt = b.load_typed(info.addr, IrType::Ptr(Box::new(info.ty.clone())));
                    b.load_typed(tgt, info.ty.clone())
                } else if info.is_pointer && info.derived_type.is_some() {
                    if local_uses_array_descriptor(info) && info.dims.is_empty() {
                        array_base_addr(b, info)
                    } else {
                        // Derived-type POINTER used as a bare Name
                        // (e.g. passed to a subroutine expecting
                        // type(t)). The consumer wants the struct
                        // address, which is what's stored in the
                        // pointer slot.
                        b.load_typed(info.addr, IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))))
                    }
                } else if info.derived_type.is_some() {
                    if info
                        .derived_type
                        .as_ref()
                        .map(|name| is_opaque_c_handle_name(name))
                        .unwrap_or(false)
                    {
                        if info.by_ref {
                            let raw_ptr = b.load_typed(info.addr, IrType::Int(IntWidth::I64));
                            let ptr = b.int_to_ptr(raw_ptr, info.ty.clone());
                            b.load_typed(ptr, info.ty.clone())
                        } else {
                            b.load_typed(info.addr, info.ty.clone())
                        }
                    } else
                    // Derived type variable: storage is `alloca [i8 x size]`.
                    // Consumers of the value treat it as a pointer to the
                    // struct (memcpy for whole-struct assignment, GEP for
                    // component access). Without this case we fell through
                    // to load_typed(info.ty) which yanked the first 8 bytes
                    // of the struct as if they were a pointer, turning
                    // `b = a` into a memcpy from the garbage address held
                    // by a's first field slot.
                    {
                        if info.allocatable {
                            array_base_addr(b, info)
                        } else if info.by_ref {
                            b.load(info.addr)
                        } else {
                            info.addr
                        }
                    }
                } else if is_complex_ty(&info.ty) {
                    if info.by_ref {
                        // by-ref complex: info.addr holds ptr-to-ptr-to-buffer.
                        // Load once to get ptr-to-buffer; caller treats as address.
                        b.load(info.addr)
                    } else {
                        // Complex variable: return the stack-buffer address.
                        // Complex is stored as [f32/f64 x 2] — callers use the address
                        // directly (memcpy for assignment, ptr for I/O, GEP for components).
                        info.addr
                    }
                } else if info.by_ref {
                    // Pass-by-reference param: load the pointer, then load through it.
                    let ptr = b.load(info.addr);
                    b.load_typed(ptr, info.ty.clone())
                } else {
                    // Use load_typed with the local's declared type to handle cases
                    // where the address pointer type doesn't exactly match (e.g.,
                    // WHERE substitution using byte-level GEP).
                    b.load_typed(info.addr, info.ty.clone())
                }
            } else {
                if let Some(sym) = st.find_symbol_any_scope(&key) {
                    if let Some(cv) = sym.const_value {
                        if let Some(type_info) = sym.type_info.as_ref() {
                            let target = type_info_to_ir_type(type_info);
                            let clamped =
                                clamp_const_to_type(ConstScalar::Int(cv as i128), &target);
                            materialize_const_scalar(b, clamped, &target)
                        } else if i32::try_from(cv).is_ok() {
                            b.const_i32(cv as i32)
                        } else {
                            b.const_i64(cv)
                        }
                    } else {
                        b.const_i32(0)
                    }
                } else {
                    b.const_i32(0)
                }
            }
        }

        Expr::BinaryOp { op, left, right } => {
            if matches!(op, BinaryOp::Concat)
                && expr_is_character_expr(b, locals, left, st, type_layouts)
                && expr_is_character_expr(b, locals, right, st, type_layouts)
            {
                let (ptr, _len) = lower_string_expr_full(
                    b,
                    locals,
                    expr,
                    st,
                    type_layouts,
                    internal_funcs,
                    contained_host_refs,
                    descriptor_params,
                );
                return ptr;
            }
            if matches!(
                op,
                BinaryOp::Eq
                    | BinaryOp::Ne
                    | BinaryOp::Lt
                    | BinaryOp::Le
                    | BinaryOp::Gt
                    | BinaryOp::Ge
            ) && (expr_is_character_expr(b, locals, left, st, type_layouts)
                || expr_is_character_expr(b, locals, right, st, type_layouts))
            {
                let (lhs_ptr, lhs_len) = lower_string_expr_full(
                    b,
                    locals,
                    left,
                    st,
                    type_layouts,
                    internal_funcs,
                    contained_host_refs,
                    descriptor_params,
                );
                let (rhs_ptr, rhs_len) = lower_string_expr_full(
                    b,
                    locals,
                    right,
                    st,
                    type_layouts,
                    internal_funcs,
                    contained_host_refs,
                    descriptor_params,
                );
                let cmp = b.call(
                    FuncRef::External("afs_compare_char".into()),
                    vec![lhs_ptr, lhs_len, rhs_ptr, rhs_len],
                    IrType::Int(IntWidth::I32),
                );
                let zero = b.const_i32(0);
                return match op {
                    BinaryOp::Eq => b.icmp(CmpOp::Eq, cmp, zero),
                    BinaryOp::Ne => b.icmp(CmpOp::Ne, cmp, zero),
                    BinaryOp::Lt => b.icmp(CmpOp::Lt, cmp, zero),
                    BinaryOp::Le => b.icmp(CmpOp::Le, cmp, zero),
                    BinaryOp::Gt => b.icmp(CmpOp::Gt, cmp, zero),
                    BinaryOp::Ge => b.icmp(CmpOp::Ge, cmp, zero),
                    _ => unreachable!(),
                };
            }
            if matches!(op, BinaryOp::And | BinaryOp::Or) {
                return lower_short_circuit_logical_expr(
                    b,
                    locals,
                    expr,
                    st,
                    type_layouts,
                    internal_funcs,
                    contained_host_refs,
                    descriptor_params,
                );
            }
            let mut lhs = lower_expr_full(
                b,
                locals,
                left,
                st,
                type_layouts,
                internal_funcs,
                contained_host_refs,
                descriptor_params,
            );
            let mut rhs = lower_expr_full(
                b,
                locals,
                right,
                st,
                type_layouts,
                internal_funcs,
                contained_host_refs,
                descriptor_params,
            );
            let lty = b
                .func()
                .value_type(lhs)
                .unwrap_or(IrType::Int(IntWidth::I32));
            let rty = b
                .func()
                .value_type(rhs)
                .unwrap_or(IrType::Int(IntWidth::I32));

            // Defined operator dispatch (INTERFACE OPERATOR(...)): if a
            // generic interface for this operator exists and a specific
            // matches the actual operand types, emit a call instead of
            // arithmetic. Needed for e.g. `type(vec) + type(vec)` — the
            // default arithmetic would ICE trying to `iadd` pointers.
            if let Some(specific) = resolve_operator_overload(
                b,
                locals,
                st,
                type_layouts,
                op,
                &lty,
                &rty,
                left,
                right,
                lhs,
                rhs,
            ) {
                return emit_resolved_operator_call(
                    b,
                    locals,
                    st,
                    type_layouts,
                    internal_funcs,
                    contained_host_refs,
                    descriptor_params,
                    &specific,
                    left,
                    right,
                    lhs,
                    rhs,
                );
            }

            // Complex arithmetic: both operands are ptr<[f32/f64 x 2]>.
            // Add/Sub operate component-wise; Mul uses (ac-bd, ad+bc).
            if is_complex_ty(&lty) || is_complex_ty(&rty) {
                let fw = if matches!(lty, IrType::Float(FloatWidth::F64))
                    || matches!(rty, IrType::Float(FloatWidth::F64))
                    || (is_complex_ty(&lty) && complex_float_width(&lty) == FloatWidth::F64)
                    || (is_complex_ty(&rty) && complex_float_width(&rty) == FloatWidth::F64)
                {
                    FloatWidth::F64
                } else {
                    FloatWidth::F32
                };
                let elem = IrType::Float(fw);
                let esz = b.const_i64(if fw == FloatWidth::F64 { 8 } else { 4 });
                let zero = b.const_i64(0);
                let lhs_buf = materialize_complex_operand(b, lhs, fw);
                let rhs_buf = materialize_complex_operand(b, rhs, fw);
                // Load components from lhs (re_l, im_l).
                let re_l_ptr = b.gep(lhs_buf, vec![zero], IrType::Int(IntWidth::I8));
                let im_l_ptr = b.gep(lhs_buf, vec![esz], IrType::Int(IntWidth::I8));
                let re_l = b.load_typed(re_l_ptr, elem.clone());
                let im_l = b.load_typed(im_l_ptr, elem.clone());
                // Load components from rhs (re_r, im_r).
                let re_r_ptr = b.gep(rhs_buf, vec![zero], IrType::Int(IntWidth::I8));
                let im_r_ptr = b.gep(rhs_buf, vec![esz], IrType::Int(IntWidth::I8));
                let re_r = b.load_typed(re_r_ptr, elem.clone());
                let im_r = b.load_typed(im_r_ptr, elem.clone());
                let arr_ty = IrType::Array(Box::new(elem.clone()), 2);
                let buf = b.alloca(arr_ty);
                let (re_res, im_res) = match op {
                    BinaryOp::Add => (b.fadd(re_l, re_r), b.fadd(im_l, im_r)),
                    BinaryOp::Sub => (b.fsub(re_l, re_r), b.fsub(im_l, im_r)),
                    BinaryOp::Mul => {
                        // (ac-bd, ad+bc)
                        let ac = b.fmul(re_l, re_r);
                        let bd = b.fmul(im_l, im_r);
                        let ad = b.fmul(re_l, im_r);
                        let bc = b.fmul(im_l, re_r);
                        (b.fsub(ac, bd), b.fadd(ad, bc))
                    }
                    BinaryOp::Div => {
                        // (a+bi)/(c+di) = ((ac+bd)/(c^2+d^2), (bc-ad)/(c^2+d^2))
                        let rr = b.fmul(re_r, re_r);
                        let ii = b.fmul(im_r, im_r);
                        let denom = b.fadd(rr, ii);
                        let ac = b.fmul(re_l, re_r);
                        let bd = b.fmul(im_l, im_r);
                        let bc = b.fmul(im_l, re_r);
                        let ad = b.fmul(re_l, im_r);
                        let real_num = b.fadd(ac, bd);
                        let imag_num = b.fsub(bc, ad);
                        (b.fdiv(real_num, denom), b.fdiv(imag_num, denom))
                    }
                    _ => (re_l, im_l), // unsupported: return lhs unchanged
                };
                let dst_re = b.gep(buf, vec![zero], IrType::Int(IntWidth::I8));
                let dst_im = b.gep(buf, vec![esz], IrType::Int(IntWidth::I8));
                b.store(re_res, dst_re);
                b.store(im_res, dst_im);
                return buf;
            }

            // Implicit type promotion: if one side is int and the other float,
            // convert the int to float (Fortran mixed-mode arithmetic).
            let result_ty = if lty.is_float() || rty.is_float() {
                let fw = match (&lty, &rty) {
                    (IrType::Float(FloatWidth::F64), _) | (_, IrType::Float(FloatWidth::F64)) => {
                        FloatWidth::F64
                    }
                    _ => FloatWidth::F32,
                };
                if lty.is_int() {
                    lhs = b.int_to_float(lhs, fw);
                }
                if rty.is_int() {
                    rhs = b.int_to_float(rhs, fw);
                }
                // Promote f32 to f64 if other is f64.
                if matches!(lty, IrType::Float(FloatWidth::F32)) && fw == FloatWidth::F64 {
                    lhs = b.float_extend(lhs, FloatWidth::F64);
                }
                if matches!(rty, IrType::Float(FloatWidth::F32)) && fw == FloatWidth::F64 {
                    rhs = b.float_extend(rhs, FloatWidth::F64);
                }
                IrType::Float(fw)
            } else {
                // Integer width promotion: widen the narrower operand to
                // match the wider one. Without this, integer(int64) + 1
                // produces an IR width mismatch (i64 + i32).
                let lw = lty.int_width().unwrap_or(IntWidth::I32);
                let rw = rty.int_width().unwrap_or(IntWidth::I32);
                let target_w = if lw.bits() >= rw.bits() { lw } else { rw };
                if lw != target_w {
                    lhs = b.int_extend(lhs, target_w, true);
                }
                if rw != target_w {
                    rhs = b.int_extend(rhs, target_w, true);
                }
                IrType::Int(target_w)
            };

            match (op, &result_ty) {
                (BinaryOp::Add, IrType::Int(_)) => b.iadd(lhs, rhs),
                (BinaryOp::Add, IrType::Float(_)) => b.fadd(lhs, rhs),
                (BinaryOp::Sub, IrType::Int(_)) => b.isub(lhs, rhs),
                (BinaryOp::Sub, IrType::Float(_)) => b.fsub(lhs, rhs),
                (BinaryOp::Mul, IrType::Int(_)) => b.imul(lhs, rhs),
                (BinaryOp::Mul, IrType::Float(_)) => b.fmul(lhs, rhs),
                (BinaryOp::Div, IrType::Int(_)) => b.idiv(lhs, rhs),
                (BinaryOp::Div, IrType::Float(_)) => b.fdiv(lhs, rhs),
                (BinaryOp::Pow, IrType::Float(_)) => b.fpow(lhs, rhs),
                (BinaryOp::Pow, IrType::Int(_)) => {
                    let fl = b.int_to_float(lhs, FloatWidth::F64);
                    let fr = b.int_to_float(rhs, FloatWidth::F64);
                    let result = b.fpow(fl, fr);
                    b.float_to_int(result, IntWidth::I32)
                }
                (BinaryOp::Eq, IrType::Int(_)) => b.icmp(CmpOp::Eq, lhs, rhs),
                (BinaryOp::Eq, IrType::Float(_)) => b.fcmp(CmpOp::Eq, lhs, rhs),
                (BinaryOp::Ne, IrType::Int(_)) => b.icmp(CmpOp::Ne, lhs, rhs),
                (BinaryOp::Ne, IrType::Float(_)) => b.fcmp(CmpOp::Ne, lhs, rhs),
                (BinaryOp::Lt, IrType::Int(_)) => b.icmp(CmpOp::Lt, lhs, rhs),
                (BinaryOp::Lt, IrType::Float(_)) => b.fcmp(CmpOp::Lt, lhs, rhs),
                (BinaryOp::Le, IrType::Int(_)) => b.icmp(CmpOp::Le, lhs, rhs),
                (BinaryOp::Le, IrType::Float(_)) => b.fcmp(CmpOp::Le, lhs, rhs),
                (BinaryOp::Gt, IrType::Int(_)) => b.icmp(CmpOp::Gt, lhs, rhs),
                (BinaryOp::Gt, IrType::Float(_)) => b.fcmp(CmpOp::Gt, lhs, rhs),
                (BinaryOp::Ge, IrType::Int(_)) => b.icmp(CmpOp::Ge, lhs, rhs),
                (BinaryOp::Ge, IrType::Float(_)) => b.fcmp(CmpOp::Ge, lhs, rhs),
                (BinaryOp::And, _) => {
                    // Coerce to Bool if not already (Fortran .AND. on integers).
                    let lbool = coerce_to_type(b, lhs, &IrType::Bool);
                    let rbool = coerce_to_type(b, rhs, &IrType::Bool);
                    b.and(lbool, rbool)
                }
                (BinaryOp::Or, _) => {
                    let lbool = coerce_to_type(b, lhs, &IrType::Bool);
                    let rbool = coerce_to_type(b, rhs, &IrType::Bool);
                    b.or(lbool, rbool)
                }
                (BinaryOp::Eqv, _) => {
                    // a .eqv. b = .not. (a .xor. b)
                    let lbool = coerce_to_type(b, lhs, &IrType::Bool);
                    let rbool = coerce_to_type(b, rhs, &IrType::Bool);
                    let both = b.and(lbool, rbool);
                    let either = b.or(lbool, rbool);
                    let not_both = b.not(both);
                    let xor = b.and(either, not_both);
                    b.not(xor)
                }
                (BinaryOp::Neqv, _) => {
                    // a .neqv. b = a .xor. b
                    let lbool = coerce_to_type(b, lhs, &IrType::Bool);
                    let rbool = coerce_to_type(b, rhs, &IrType::Bool);
                    let both = b.and(lbool, rbool);
                    let either = b.or(lbool, rbool);
                    let not_both = b.not(both);
                    b.and(either, not_both)
                }
                (BinaryOp::Concat, _) => b.runtime_call(
                    RuntimeFunc::StringConcat,
                    vec![lhs, rhs],
                    IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))),
                ),
                _ => b.iadd(lhs, rhs), // fallback for defined ops
            }
        }

        Expr::UnaryOp { op, operand } => {
            let val = lower_expr_full(
                b,
                locals,
                operand,
                st,
                type_layouts,
                internal_funcs,
                contained_host_refs,
                descriptor_params,
            );
            let ty = b
                .func()
                .value_type(val)
                .unwrap_or(IrType::Int(IntWidth::I32));
            match (op, &ty) {
                (UnaryOp::Minus, IrType::Int(_)) => b.ineg(val),
                (UnaryOp::Minus, IrType::Float(_)) => b.fneg(val),
                (UnaryOp::Plus, _) => val,
                (UnaryOp::Not, _) => b.not(val),
                _ => val,
            }
        }

        Expr::ParenExpr { inner } => lower_expr_full(
            b,
            locals,
            inner,
            st,
            type_layouts,
            internal_funcs,
            contained_host_refs,
            descriptor_params,
        ),

        Expr::FunctionCall { callee, args } => {
            if args.len() == 1
                && expr_is_character_expr(b, locals, callee, st, type_layouts)
                && !expr_is_array_designator(b, locals, callee, st, type_layouts)
                && !expr_is_callable_character_callee(b, locals, callee, st, type_layouts)
            {
                match &args[0].value {
                    crate::ast::expr::SectionSubscript::Range { start, end, .. } => {
                        let (base_ptr, base_len) =
                            lower_string_expr_with_layouts(b, locals, callee, st, type_layouts);
                        let (ptr, _len) = lower_substring_full(
                            b,
                            locals,
                            st,
                            base_ptr,
                            base_len,
                            start.as_ref(),
                            end.as_ref(),
                            type_layouts,
                            internal_funcs,
                            contained_host_refs,
                            descriptor_params,
                        );
                        return ptr;
                    }
                    crate::ast::expr::SectionSubscript::Element(idx_expr) => {
                        let (base_ptr, base_len) =
                            lower_string_expr_with_layouts(b, locals, callee, st, type_layouts);
                        let (ptr, _len) = lower_substring_full(
                            b,
                            locals,
                            st,
                            base_ptr,
                            base_len,
                            Some(idx_expr),
                            Some(idx_expr),
                            type_layouts,
                            internal_funcs,
                            contained_host_refs,
                            descriptor_params,
                        );
                        return ptr;
                    }
                }
            }
            if let Expr::Name { name } = &callee.node {
                let key = name.to_lowercase();
                let procptr_target = procedure_pointer_call_target(b, locals, st, &key);
                let signature_key = procptr_target
                    .as_ref()
                    .map(|(_, sig_key)| sig_key.clone())
                    .unwrap_or_else(|| key.clone());
                let has_named_interface = !internal_funcs
                    .is_some_and(|funcs| funcs.contains_key(&key))
                    && find_named_interface_symbol(st, &key).is_some();

                // Check if this is an array element or section access.
                if let Some(info) = locals.get(&key) {
                    if local_is_array_like(info) {
                        let has_range = args.iter().any(|a| {
                            matches!(a.value, crate::ast::expr::SectionSubscript::Range { .. })
                        });
                        if has_range {
                            return lower_array_section(b, locals, info, args, st, type_layouts);
                        }
                        return lower_array_element(b, locals, info, args, st, type_layouts);
                    }
                }

                // Check for pointer intrinsics (ASSOCIATED) first —
                // these work on every pointer shape and don't care
                // about the array-intrinsic filter.
                if !has_named_interface {
                    if let Some(result) =
                        lower_pointer_intrinsic(b, locals, &key, args, st, type_layouts)
                    {
                        return result;
                    }

                    if let Some(result) =
                        lower_scalar_allocated_intrinsic(b, locals, &key, args, st, type_layouts)
                    {
                        return result;
                    }

                    if let Some(result) = lower_logical_reduction_intrinsic_ast(
                        b,
                        &key,
                        args,
                        locals,
                        st,
                        type_layouts,
                        internal_funcs,
                        contained_host_refs,
                        descriptor_params,
                    ) {
                        return result;
                    }

                    // Check for array intrinsics (SIZE, SUM, etc.) that need descriptor addresses.
                    if let Some(result) =
                            lower_array_intrinsic(
                                b,
                                locals,
                                &key,
                                args,
                                st,
                                type_layouts,
                                internal_funcs,
                                contained_host_refs,
                                descriptor_params,
                            )
                    {
                        return result;
                    }

                    // Try character intrinsics (need access to locals for CharKind).
                    if let Some(result) = lower_char_intrinsic(
                        b,
                        &key,
                        args,
                        locals,
                        st,
                        type_layouts,
                        internal_funcs,
                        contained_host_refs,
                        descriptor_params,
                    ) {
                        return result;
                    }
                }

                // PRESENT(x): check if optional dummy argument x was passed.
                // By-ref params are stored as `alloca Ptr<T>` in locals; when the
                // caller omits an optional arg it passes null (0). Load the stored
                // pointer and compare to zero → non-zero means present.
                if key == "present" {
                    if let Some(arg0) = args.first() {
                        if let crate::ast::expr::SectionSubscript::Element(e) = &arg0.value {
                            if let Expr::Name { name: arg_name } = &e.node {
                                let akey = arg_name.to_lowercase();
                                if let Some(info) = locals.get(&akey) {
                                    if info.by_ref {
                                        // Load the incoming pointer stored in the by-ref slot.
                                        // If absent, caller passes 0; if present, non-zero address.
                                        let ptr_val = b.load(info.addr);
                                        let zero = b.const_i64(0);
                                        return b.icmp(CmpOp::Ne, ptr_val, zero);
                                    }
                                }
                            }
                        }
                    }
                    // If we can't resolve it (non-standard usage), assume present.
                    return b.const_bool(true);
                }

                // c_loc(x): return the address of the target itself as an
                // i64 integer (matching type(c_ptr)). This must bypass the
                // normal by-ref argument path because character arguments use
                // temporary pointer slots there, while c_loc needs the real
                // underlying element/storage address.
                if key == "c_loc" {
                    if let Some(arg0) = args.first() {
                        if let crate::ast::expr::SectionSubscript::Element(e) = &arg0.value {
                            if let Expr::Name { name } = &e.node {
                                if let Some(info) = locals.get(&name.to_lowercase()) {
                                    let addr = if info.by_ref {
                                        if info.descriptor_arg {
                                            array_data_ptr_for_call(b, info)
                                        } else if info.char_kind != CharKind::None
                                            && info.dims.is_empty()
                                        {
                                            if let Some((ptr, _)) =
                                                char_addr_and_runtime_len(b, e, locals)
                                            {
                                                ptr
                                            } else {
                                                b.load(info.addr)
                                            }
                                        } else {
                                            b.load(info.addr)
                                        }
                                    } else if !info.dims.is_empty()
                                        || local_uses_array_descriptor(info)
                                    {
                                        array_data_ptr_for_call(b, info)
                                    } else if info.char_kind != CharKind::None {
                                        if let Some((ptr, _)) =
                                            char_addr_and_runtime_len(b, e, locals)
                                        {
                                            ptr
                                        } else {
                                            info.addr
                                        }
                                    } else {
                                        info.addr
                                    };
                                    return b.ptr_to_int(addr);
                                }
                            }

                            if let Expr::FunctionCall {
                                callee,
                                args: subscripts,
                            } = &e.node
                            {
                                if let Expr::Name { name } = &callee.node {
                                    if let Some(info) = locals.get(&name.to_lowercase()) {
                                        if info.char_kind != CharKind::None {
                                            let addr = if local_uses_array_descriptor(info)
                                                || inline_char_array_storage(info)
                                            {
                                                char_array_element_ptr_and_len(
                                                    b,
                                                    locals,
                                                    info,
                                                    subscripts,
                                                    st,
                                                    type_layouts,
                                                )
                                                .map(|(ptr, _)| ptr)
                                                .unwrap_or_else(|| {
                                                    lower_array_element_addr(
                                                        b,
                                                        locals,
                                                        info,
                                                        subscripts,
                                                        st,
                                                        type_layouts,
                                                    )
                                                })
                                            } else {
                                                lower_array_element(
                                                    b,
                                                    locals,
                                                    info,
                                                    subscripts,
                                                    st,
                                                    type_layouts,
                                                )
                                            };
                                            return b.ptr_to_int(addr);
                                        }
                                        if !info.dims.is_empty()
                                            || local_uses_array_descriptor(info)
                                        {
                                            let addr = lower_array_element_addr(
                                                b,
                                                locals,
                                                info,
                                                subscripts,
                                                st,
                                                type_layouts,
                                            );
                                            return b.ptr_to_int(addr);
                                        }
                                    }
                                }
                            }

                            let addr = lower_arg_by_ref(b, locals, e, st);
                            return b.ptr_to_int(addr);
                        }
                    }
                }

                // c_funloc(f): return the entry address of the procedure.
                if key == "c_funloc" {
                    if let Some(arg0) = args.first() {
                        if let crate::ast::expr::SectionSubscript::Element(e) = &arg0.value {
                            let addr = lower_arg_by_ref(b, locals, e, st);
                            return b.ptr_to_int(addr);
                        }
                    }
                }

                // abs(z) for complex: sqrt(re² + im²).
                // Must be handled before generic intrinsic lowering because
                // complex values are pointers to [f32/f64 x 2] buffers.
                if (key == "abs" || key == "cabs" || key == "cdabs" || key == "zabs")
                    && args.len() == 1
                {
                    if let Some(arg0) = args.first() {
                        if let crate::ast::expr::SectionSubscript::Element(e) = &arg0.value {
                            let val = lower_expr_full(
                                b,
                                locals,
                                e,
                                st,
                                type_layouts,
                                internal_funcs,
                                contained_host_refs,
                                descriptor_params,
                            );
                            let ty = b
                                .func()
                                .value_type(val)
                                .unwrap_or(IrType::Int(IntWidth::I32));
                            if is_complex_ty(&ty) {
                                let fw = complex_float_width(&ty);
                                let elem = IrType::Float(fw);
                                let esz = b.const_i64(if fw == FloatWidth::F64 { 8 } else { 4 });
                                let zero = b.const_i64(0);
                                let re_ptr = b.gep(val, vec![zero], IrType::Int(IntWidth::I8));
                                let im_ptr = b.gep(val, vec![esz], IrType::Int(IntWidth::I8));
                                let re = b.load_typed(re_ptr, elem.clone());
                                let im = b.load_typed(im_ptr, elem);
                                let re2 = b.fmul(re, re);
                                let im2 = b.fmul(im, im);
                                let sum = b.fadd(re2, im2);
                                return b.fsqrt(sum);
                            }
                        }
                    }
                }

                // Keyword-argument reordering for function calls
                // (symmetric with the Stmt::Call path). Binds by name
                // when the callee's arg_order is resolvable.
                let original_args = args;
                let resolution_arg_vals: Vec<ValueId> = original_args
                    .iter()
                    .map(|arg| match &arg.value {
                        crate::ast::expr::SectionSubscript::Element(e) => {
                            generic_dispatch_probe_value(
                                b,
                                locals,
                                e,
                                st,
                                type_layouts,
                                internal_funcs,
                                contained_host_refs,
                                descriptor_params,
                            )
                        }
                        _ => b.const_i32(0),
                    })
                    .collect();

                let fallback_to_structure_ctor = has_named_interface
                    && type_layouts.is_some_and(|tl| tl.get(&key).is_some())
                    && resolve_generic_call_actuals(
                        st,
                        b,
                        Some(locals),
                        &key,
                        original_args,
                        &resolution_arg_vals,
                        type_layouts,
                    )
                    .is_none();

                if !has_named_interface || fallback_to_structure_ctor {
                    if let Some(tmp) = lower_structure_constructor_expr(
                        b,
                        locals,
                        &key,
                        args,
                        st,
                        type_layouts,
                        internal_funcs,
                        contained_host_refs,
                        descriptor_params,
                    ) {
                        return tmp;
                    }
                }

                // Try intrinsic lowering first (intrinsics use values, not references).
                let intrinsic_arg_slots = reorder_args_by_keyword_slots(original_args, &key, st);
                let intrinsic_args: Vec<crate::ast::expr::Argument> =
                    intrinsic_arg_slots.iter().flatten().cloned().collect();
                let intrinsic_arg_vals: Vec<ValueId> = intrinsic_args
                    .iter()
                    .map(|a| match &a.value {
                        crate::ast::expr::SectionSubscript::Element(e) => {
                            generic_dispatch_probe_value(
                                b,
                                locals,
                                e,
                                st,
                                type_layouts,
                                internal_funcs,
                                contained_host_refs,
                                descriptor_params,
                            )
                        }
                        _ => b.const_i32(0),
                    })
                    .collect();

                let intrinsic_result = lower_intrinsic(b, &key, &intrinsic_arg_vals);
                if !has_named_interface {
                    if let Some(result) = intrinsic_result {
                        let coerced = operator_expr_type_info(expr, Some(locals), st, type_layouts)
                            .and_then(|ti| match ti {
                                crate::sema::symtab::TypeInfo::Integer { .. }
                                | crate::sema::symtab::TypeInfo::Real { .. }
                                | crate::sema::symtab::TypeInfo::DoublePrecision
                                | crate::sema::symtab::TypeInfo::Complex { .. }
                                | crate::sema::symtab::TypeInfo::Logical { .. } => {
                                    Some(type_info_to_ir_type(&ti))
                                }
                                _ => None,
                            })
                            .map(|target_ty| {
                                // Complex intrinsics materialize pointer-backed
                                // two-lane buffers. Keep that pointer form at the
                                // expression boundary so downstream complex
                                // assignment/call paths can memcpy from the
                                // buffer address instead of treating lane 0 as a
                                // fake pointer.
                                let result_ty = b.func().value_type(result);
                                if is_complex_ty(&target_ty)
                                    && matches!(
                                        result_ty,
                                        Some(IrType::Ptr(ref inner))
                                            if inner.as_ref() == &target_ty
                                    )
                                {
                                    result
                                } else {
                                    coerce_to_type(b, result, &target_ty)
                                }
                            })
                            .unwrap_or(result);
                        return coerced;
                    }
                }

                // Resolve generic interface names to specific procedures.
                // For a NamedInterface callee, failing to resolve means
                // the call is ill-typed (wrong arity, wrong kind, or no
                // matching specific). Emit a compile-time diagnostic
                // instead of silently falling back to the generic name,
                // which would either mismatch the callee ABI or produce
                // an unresolved link-time symbol.
                let resolved_generic = if procptr_target.is_some() {
                    None
                } else {
                    resolve_generic_call_actuals(
                        st,
                        b,
                        Some(locals),
                        &key,
                        original_args,
                        &resolution_arg_vals,
                        type_layouts,
                    )
                };
                let (call_name, callee_key) = if procptr_target.is_some() {
                    (String::new(), signature_key.clone())
                } else if let Some(candidate) = resolved_generic.as_ref() {
                    resolved_symbol_call_target_for_candidate(st, candidate)
                } else {
                    if let Some(result) =
                        lower_pointer_intrinsic(b, locals, &key, args, st, type_layouts)
                    {
                        return result;
                    }

                    if let Some(result) =
                        lower_scalar_allocated_intrinsic(b, locals, &key, args, st, type_layouts)
                    {
                        return result;
                    }

                    if let Some(result) = lower_logical_reduction_intrinsic_ast(
                        b,
                        &key,
                        args,
                        locals,
                        st,
                        type_layouts,
                        internal_funcs,
                        contained_host_refs,
                        descriptor_params,
                    ) {
                        return result;
                    }

                    if let Some(result) = lower_array_intrinsic(
                        b,
                        locals,
                        &key,
                        args,
                        st,
                        type_layouts,
                        internal_funcs,
                        contained_host_refs,
                        descriptor_params,
                    ) {
                        return result;
                    }

                    if let Some(result) = lower_char_intrinsic(
                        b,
                        &key,
                        args,
                        locals,
                        st,
                        type_layouts,
                        internal_funcs,
                        contained_host_refs,
                        descriptor_params,
                    ) {
                        return result;
                    }

                    if let Some(result) = intrinsic_result {
                        return result;
                    }
                    if let Some(specifics) = named_interface_specifics(st, &key) {
                        eprintln!(
                            "armfortas: error: {}:{}: no specific procedure of generic '{}' matches the actual arguments; candidates: [{}]",
                            expr.span.start.line,
                            expr.span.start.col,
                            name,
                            specifics.join(", "),
                        );
                        let _ = std::io::stderr().flush();
                        std::process::exit(1);
                    }
                    resolved_symbol_call_target(st, &key, name)
                };
                let arg_slots = reorder_args_by_keyword_slots(
                    original_args,
                    if procptr_target.is_some() {
                        &signature_key
                    } else {
                        &callee_key
                    },
                    st,
                );
                let arg_slots = if let Some(candidate) = resolved_generic.as_ref() {
                    reorder_args_for_specific_candidate(st, candidate, original_args)
                        .unwrap_or(arg_slots)
                } else {
                    arg_slots
                };
                let abi_lookup_keys = procedure_abi_lookup_keys(
                    st,
                    &[call_name.as_str(), &callee_key, &signature_key, &key],
                );
                let abi_primary_key = abi_lookup_keys
                    .first()
                    .map(String::as_str)
                    .unwrap_or(callee_key.as_str());
                if procptr_target.is_none() {
                    if let Some(hidden_abi) = first_procedure_lookup(&abi_lookup_keys, |k| {
                        callee_hidden_result_abi(st, k)
                    }) {
                        if let Some(bytes) = hidden_result_temp_bytes_for_callee(
                            st,
                            type_layouts,
                            &abi_lookup_keys,
                            hidden_abi,
                        ) {
                            let desc =
                                b.alloca(IrType::Array(Box::new(IrType::Int(IntWidth::I8)), bytes));
                            let zero_i32 = b.const_i32(0);
                            let size = b.const_i64(bytes as i64);
                            b.call(
                                FuncRef::External("memset".into()),
                                vec![desc, zero_i32, size],
                                IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))),
                            );
                            emit_named_function_call(
                                b,
                                locals,
                                st,
                                type_layouts,
                                internal_funcs,
                                contained_host_refs,
                                descriptor_params,
                                name,
                                original_args,
                                Some(desc),
                                true,
                                IrType::Void,
                            );
                            return desc;
                        }
                    }
                }
                let callee_value_args =
                    first_procedure_lookup(&abi_lookup_keys, |k| callee_value_arg_mask(st, k));
                let callee_descriptor_args = first_procedure_lookup(&abi_lookup_keys, |k| {
                    descriptor_params.and_then(|m| cached_param_mask_for_lookup(st, m, k))
                });
                let callee_string_descriptor_args = first_procedure_lookup(&abi_lookup_keys, |k| {
                    callee_string_descriptor_arg_mask(st, k)
                });
                let callee_bind_c_char_args = first_procedure_lookup(&abi_lookup_keys, |k| {
                    callee_bind_c_char_arg_mask(st, k)
                });
                let callee_pointer_args =
                    first_procedure_lookup(&abi_lookup_keys, |k| callee_pointer_arg_mask(st, k));
                let callee_class_args =
                    first_procedure_lookup(&abi_lookup_keys, |k| callee_class_arg_mask(st, k));
                let opt_flags =
                    first_procedure_lookup(&abi_lookup_keys, |k| callee_optional_arg_mask(st, k));
                let mut ref_arg_vals: Vec<ValueId> = Vec::with_capacity(arg_slots.len());
                for (i, slot) in arg_slots.iter().enumerate() {
                    let is_value = callee_value_args
                        .as_ref()
                        .map(|mask| mask.get(i).copied().unwrap_or(false))
                        .unwrap_or(false);
                    let wants_descriptor = callee_descriptor_args
                        .as_ref()
                        .map(|mask| mask.get(i).copied().unwrap_or(false))
                        .unwrap_or(false);
                    let wants_string_descriptor = callee_string_descriptor_args
                        .as_ref()
                        .map(|mask| mask.get(i).copied().unwrap_or(false))
                        .unwrap_or(false);
                    let wants_bind_c_char = callee_bind_c_char_args
                        .as_ref()
                        .map(|mask| mask.get(i).copied().unwrap_or(false))
                        .unwrap_or(false);
                    let wants_descriptor = wants_descriptor && !wants_bind_c_char;
                    let wants_polymorphic_descriptor = wants_descriptor
                        && callee_class_args
                            .as_ref()
                            .map(|mask| mask.get(i).copied().unwrap_or(false))
                            .unwrap_or(false);
                    let wants_string_descriptor = wants_string_descriptor && !wants_bind_c_char;
                    let wants_pointer = callee_pointer_args
                        .as_ref()
                        .map(|mask| mask.get(i).copied().unwrap_or(false))
                        .unwrap_or(false);
                    let value = match slot {
                        Some(arg) => match &arg.value {
                            crate::ast::expr::SectionSubscript::Element(e) => {
                                if is_value && wants_bind_c_char {
                                    lower_bind_c_char_value_arg(
                                        b,
                                        locals,
                                        e,
                                        st,
                                        type_layouts,
                                        internal_funcs,
                                        contained_host_refs,
                                        descriptor_params,
                                    )
                                } else if is_value {
                                    let raw = lower_expr_full(
                                        b,
                                        locals,
                                        e,
                                        st,
                                        type_layouts,
                                        internal_funcs,
                                        contained_host_refs,
                                        descriptor_params,
                                    );
                                    coerce_value_call_arg(b, st, abi_primary_key, i, raw)
                                } else if wants_descriptor {
                                    lower_arg_descriptor(
                                        b,
                                        locals,
                                        e,
                                        st,
                                        type_layouts,
                                        wants_polymorphic_descriptor,
                                    )
                                } else if wants_string_descriptor {
                                    lower_arg_string_descriptor(b, locals, e, st, type_layouts)
                                } else if wants_bind_c_char {
                                    lower_bind_c_char_arg_raw(
                                        b,
                                        locals,
                                        e,
                                        st,
                                        type_layouts,
                                        internal_funcs,
                                        contained_host_refs,
                                        descriptor_params,
                                    )
                                } else if wants_pointer {
                                    lower_pointer_dummy_actual(
                                        b,
                                        locals,
                                        e,
                                        st,
                                        type_layouts,
                                        internal_funcs,
                                        contained_host_refs,
                                        descriptor_params,
                                    )
                                    .unwrap_or_else(|| {
                                        lower_arg_by_ref_full(
                                            b,
                                            locals,
                                            e,
                                            st,
                                            type_layouts,
                                            internal_funcs,
                                            contained_host_refs,
                                            descriptor_params,
                                        )
                                    })
                                } else {
                                    lower_arg_by_ref_full(
                                        b,
                                        locals,
                                        e,
                                        st,
                                        type_layouts,
                                        internal_funcs,
                                        contained_host_refs,
                                        descriptor_params,
                                    )
                                }
                            }
                            _ => b.const_i32(0),
                        },
                        None => missing_optional_call_arg(b, st, abi_primary_key, i, is_value),
                    };
                    ref_arg_vals.push(value);
                }
                if let Some(opt_flags) = opt_flags {
                    for flag in opt_flags.iter().skip(ref_arg_vals.len()) {
                        if *flag {
                            ref_arg_vals.push(b.const_i64(0));
                        }
                    }
                }
                let callee_char_len_star_args =
                    first_procedure_lookup(&abi_lookup_keys, |k| callee_char_len_star_mask(st, k));

                if let Some(cls_flags) = &callee_char_len_star_args {
                    for (i, flag) in cls_flags.iter().enumerate() {
                        if !*flag || i >= arg_slots.len() {
                            continue;
                        }
                        if let Some(arg) = &arg_slots[i] {
                            if let crate::ast::expr::SectionSubscript::Element(e) = &arg.value {
                                ref_arg_vals.push(
                                    actual_char_arg_runtime_len(
                                        b,
                                        locals,
                                        None,
                                        e,
                                        st,
                                        type_layouts,
                                        internal_funcs,
                                        contained_host_refs,
                                        descriptor_params,
                                    )
                                    .unwrap_or_else(|| b.const_i64(0)),
                                );
                            } else {
                                ref_arg_vals.push(b.const_i64(0));
                            }
                        } else {
                            ref_arg_vals.push(b.const_i64(0));
                        }
                    }
                }

                // Host-association closure-passing ABI: append trailing
                // pointer args for each host-local the callee references.
                // Prefer the generic-resolved name's map entry; fall back
                // to the unresolved key so calls that don't go through
                // generic dispatch still thread host vars.
                let closure_key = if contained_host_refs
                    .map(|m| m.contains_key(&callee_key))
                    .unwrap_or(false)
                {
                    &callee_key
                } else {
                    &key
                };
                if procptr_target.is_none() {
                    append_host_closure_args_raw(
                        b,
                        locals,
                        contained_host_refs,
                        closure_key,
                        &mut ref_arg_vals,
                    );
                }

                // Look up callee return type from symbol table.
                let ret_ty =
                    first_procedure_lookup(&abi_lookup_keys, |k| callee_return_ir_type(st, k))
                        .unwrap_or(IrType::Int(IntWidth::I32));
                let func_ref = if let Some((target, _)) = procptr_target {
                    FuncRef::Indirect(target)
                } else {
                    same_unit_func_ref(
                        st,
                        b.func().name.as_str(),
                        internal_funcs,
                        &[&callee_key, &signature_key, &key],
                        call_name,
                    )
                };
                let call_result = b.call(func_ref, ref_arg_vals, ret_ty);
                if let Some(tl) = type_layouts {
                    if let Some(type_name) = first_procedure_lookup(&abi_lookup_keys, |k| {
                        callee_return_stabilized_derived_type_name(st, k)
                    }) {
                        return stabilize_derived_call_result(b, tl, &type_name, call_result);
                    }
                }
                call_result
            } else if let Expr::ComponentAccess { base, component } = &callee.node {
                if let Some(tl) = type_layouts {
                    if let Some(Some(result)) = emit_polymorphic_component_bound_dispatch(
                        b,
                        locals,
                        st,
                        type_layouts,
                        internal_funcs,
                        contained_host_refs,
                        None,
                        descriptor_params,
                        callee.span,
                        base,
                        component,
                        args,
                        None,
                    ) {
                        return result;
                    }
                    if let Some(info) = component_intrinsic_local_info(b, locals, callee, st, tl) {
                        let has_range = args.iter().any(|a| {
                            matches!(a.value, crate::ast::expr::SectionSubscript::Range { .. })
                        });
                        if has_range {
                            return lower_array_section(b, locals, &info, args, st, type_layouts);
                        }
                        return lower_array_element(b, locals, &info, args, st, type_layouts);
                    }

                    if let Some((obj_addr, type_name)) =
                        resolve_component_base_for_method(b, locals, base, st, tl)
                    {
                        if let Some(layout) = tl.get(&type_name) {
                            let bp = resolved_bound_proc_for_call(
                                b,
                                locals,
                                st,
                                layout,
                                component,
                                args,
                                type_layouts,
                                internal_funcs,
                                contained_host_refs,
                                descriptor_params,
                            )
                            .or_else(|| layout.bound_proc(component))
                            .unwrap_or_else(|| {
                                fail_unmatched_bound_proc_resolution(callee.span, layout, component)
                            });
                                let target = bp.target_name.clone();
                                let target_key = abi_key_for_link_name(st, &target)
                                    .unwrap_or_else(|| bp.abi_name.clone());
                                let call_name = target.clone();
                                let nopass = bp.nopass;
                                let arg_slots = reorder_args_by_keyword_slots_with_formal_skip(
                                    args,
                                    &target_key,
                                    st,
                                    if nopass { 0 } else { 1 },
                                );
                                let abi_lookup_keys = procedure_abi_lookup_keys(
                                    st,
                                    &[call_name.as_str(), &target_key],
                                );
                                let abi_primary_key = abi_lookup_keys
                                    .first()
                                    .map(String::as_str)
                                    .unwrap_or(target_key.as_str());
                                if let Some(hidden_abi) =
                                    first_procedure_lookup(&abi_lookup_keys, |k| {
                                        callee_hidden_result_abi(st, k)
                                    })
                                {
                                    if let Some(bytes) = hidden_result_temp_bytes_for_callee(
                                        st,
                                        type_layouts,
                                        &abi_lookup_keys,
                                        hidden_abi,
                                    ) {
                                        let desc = b.alloca(IrType::Array(
                                            Box::new(IrType::Int(IntWidth::I8)),
                                            bytes,
                                        ));
                                        let zero_i32 = b.const_i32(0);
                                        let size = b.const_i64(bytes as i64);
                                        b.call(
                                            FuncRef::External("memset".into()),
                                            vec![desc, zero_i32, size],
                                            IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))),
                                        );
                                        emit_bound_function_call(
                                            b,
                                            locals,
                                            st,
                                            type_layouts,
                                            internal_funcs,
                                            contained_host_refs,
                                            descriptor_params,
                                            callee.span,
                                            base,
                                            component,
                                            args,
                                            Some(desc),
                                            IrType::Void,
                                        );
                                        return desc;
                                    }
                                }
                                let callee_value_args =
                                    first_procedure_lookup(&abi_lookup_keys, |k| {
                                        callee_value_arg_mask(st, k)
                                    });
                                let callee_descriptor_args =
                                    first_procedure_lookup(&abi_lookup_keys, |k| {
                                        descriptor_params
                                            .and_then(|m| cached_param_mask_for_lookup(st, m, k))
                                    });
                                let callee_string_descriptor_args =
                                    first_procedure_lookup(&abi_lookup_keys, |k| {
                                        callee_string_descriptor_arg_mask(st, k)
                                    });
                                let callee_bind_c_char_args =
                                    first_procedure_lookup(&abi_lookup_keys, |k| {
                                        callee_bind_c_char_arg_mask(st, k)
                                    });
                                let callee_pointer_args =
                                    first_procedure_lookup(&abi_lookup_keys, |k| {
                                        callee_pointer_arg_mask(st, k)
                                    });
                                let opt_flags = first_procedure_lookup(&abi_lookup_keys, |k| {
                                    callee_optional_arg_mask(st, k)
                                });
                                let callee_char_len_star_args =
                                    first_procedure_lookup(&abi_lookup_keys, |k| {
                                        callee_char_len_star_mask(st, k)
                                    });

                                let mut call_args = Vec::with_capacity(arg_slots.len() + 1);
                                for (i, slot) in arg_slots.iter().enumerate() {
                                    if !nopass && i == 0 {
                                        let wants_bind_c_char = callee_bind_c_char_args
                                            .as_ref()
                                            .map(|mask| mask.first().copied().unwrap_or(false))
                                            .unwrap_or(false);
                                        let wants_descriptor = callee_descriptor_args
                                            .as_ref()
                                            .map(|mask| mask.first().copied().unwrap_or(false))
                                            .unwrap_or(false)
                                            && !wants_bind_c_char;
                                        call_args.push(if wants_descriptor {
                                            lower_arg_descriptor(
                                                b,
                                                locals,
                                                base,
                                                st,
                                                type_layouts,
                                                false,
                                            )
                                        } else {
                                            obj_addr
                                        });
                                        continue;
                                    }
                                    let is_value = callee_value_args
                                        .as_ref()
                                        .map(|mask| mask.get(i).copied().unwrap_or(false))
                                        .unwrap_or(false);
                                    let wants_descriptor = callee_descriptor_args
                                        .as_ref()
                                        .map(|mask| mask.get(i).copied().unwrap_or(false))
                                        .unwrap_or(false);
                                    let wants_string_descriptor = callee_string_descriptor_args
                                        .as_ref()
                                        .map(|mask| mask.get(i).copied().unwrap_or(false))
                                        .unwrap_or(false);
                                    let wants_bind_c_char = callee_bind_c_char_args
                                        .as_ref()
                                        .map(|mask| mask.get(i).copied().unwrap_or(false))
                                        .unwrap_or(false);
                                    let wants_descriptor = wants_descriptor && !wants_bind_c_char;
                                    let wants_string_descriptor =
                                        wants_string_descriptor && !wants_bind_c_char;
                                    let wants_pointer = callee_pointer_args
                                        .as_ref()
                                        .map(|mask| mask.get(i).copied().unwrap_or(false))
                                        .unwrap_or(false);
                                    let value = match slot {
                                        Some(arg) => match &arg.value {
                                            crate::ast::expr::SectionSubscript::Element(e) => {
                                                if is_value && wants_bind_c_char {
                                                    lower_bind_c_char_value_arg(
                                                        b,
                                                        locals,
                                                        e,
                                                        st,
                                                        type_layouts,
                                                        internal_funcs,
                                                        contained_host_refs,
                                                        descriptor_params,
                                                    )
                                                } else if is_value {
                                                    let raw = lower_expr_full(
                                                        b,
                                                        locals,
                                                        e,
                                                        st,
                                                        type_layouts,
                                                        internal_funcs,
                                                        contained_host_refs,
                                                        descriptor_params,
                                                    );
                                                    coerce_value_call_arg(
                                                        b,
                                                        st,
                                                        abi_primary_key,
                                                        i,
                                                        raw,
                                                    )
                                                } else if wants_descriptor {
                                                    lower_arg_descriptor(
                                                        b,
                                                        locals,
                                                        e,
                                                        st,
                                                        type_layouts,
                                                        false,
                                                    )
                                                } else if wants_string_descriptor {
                                                    lower_arg_string_descriptor(
                                                        b,
                                                        locals,
                                                        e,
                                                        st,
                                                        type_layouts,
                                                    )
                                                } else if wants_bind_c_char {
                                                    lower_bind_c_char_arg_raw(
                                                        b,
                                                        locals,
                                                        e,
                                                        st,
                                                        type_layouts,
                                                        internal_funcs,
                                                        contained_host_refs,
                                                        descriptor_params,
                                                    )
                                                } else if wants_pointer {
                                                    lower_pointer_dummy_actual(
                                                        b,
                                                        locals,
                                                        e,
                                                        st,
                                                        type_layouts,
                                                        internal_funcs,
                                                        contained_host_refs,
                                                        descriptor_params,
                                                    )
                                                    .unwrap_or_else(|| {
                                                        lower_arg_by_ref_full(
                                                            b,
                                                            locals,
                                                            e,
                                                            st,
                                                            type_layouts,
                                                            internal_funcs,
                                                            contained_host_refs,
                                                            descriptor_params,
                                                        )
                                                    })
                                                } else {
                                                    lower_arg_by_ref_full(
                                                        b,
                                                        locals,
                                                        e,
                                                        st,
                                                        type_layouts,
                                                        internal_funcs,
                                                        contained_host_refs,
                                                        descriptor_params,
                                                    )
                                                }
                                            }
                                            _ => b.const_i32(0),
                                        },
                                        None => missing_optional_call_arg(
                                            b,
                                            st,
                                            abi_primary_key,
                                            i,
                                            is_value,
                                        ),
                                    };
                                    call_args.push(value);
                                }
                                if let Some(opt_flags) = opt_flags {
                                    for flag in opt_flags.iter().skip(call_args.len()) {
                                        if *flag {
                                            call_args.push(b.const_i64(0));
                                        }
                                    }
                                }
                                if let Some(cls_flags) = &callee_char_len_star_args {
                                    for (i, flag) in cls_flags.iter().enumerate() {
                                        if !*flag || i >= arg_slots.len() {
                                            continue;
                                        }
                                        if let Some(arg) = &arg_slots[i] {
                                            if let crate::ast::expr::SectionSubscript::Element(e) =
                                                &arg.value
                                            {
                                                call_args.push(
                                                    actual_char_arg_runtime_len(
                                                        b,
                                                        locals,
                                                        None,
                                                        e,
                                                        st,
                                                        type_layouts,
                                                        internal_funcs,
                                                        contained_host_refs,
                                                        descriptor_params,
                                                    )
                                                    .unwrap_or_else(|| b.const_i64(0)),
                                                );
                                            } else {
                                                call_args.push(b.const_i64(0));
                                            }
                                        } else {
                                            call_args.push(b.const_i64(0));
                                        }
                                    }
                                }

                                let ret_ty = first_procedure_lookup(&abi_lookup_keys, |k| {
                                    callee_return_ir_type(st, k)
                                })
                                .unwrap_or(IrType::Int(IntWidth::I32));
                                let call_result =
                                    b.call(FuncRef::External(call_name), call_args, ret_ty);
                                if let Some(tl) = type_layouts {
                                    if let Some(type_name) =
                                        callee_return_stabilized_derived_type_name(st, &target_key)
                                    {
                                        return stabilize_derived_call_result(
                                            b,
                                            tl,
                                            &type_name,
                                            call_result,
                                        );
                                    }
                                }
                                return call_result;
                        }
                    }
                    reject_unsupported_polymorphic_component_method_base(
                        callee.span,
                        base,
                        locals,
                        st,
                        tl,
                    );
                }
                b.const_i32(0)
            } else {
                b.const_i32(0)
            }
        }

        Expr::ComponentAccess { base, component } => {
            if let Some(tl) = type_layouts {
                if let Expr::Name { name } = &base.node {
                    if let Some(value) =
                        lower_parameter_derived_component_const(b, st, tl, name, component)
                    {
                        return value;
                    }
                }
                // Common case: base is a Name or chained ComponentAccess.
                let resolved = resolve_component_base(b, locals, base, st, tl);
                // Inline case: base is a call that returns a derived type,
                // e.g. `add_t(a, b)%x`.  resolve_component_base doesn't
                // know how to lower a FunctionCall, so handle it here.
                // The call itself evaluates to a ptr<i8> pointing at the
                // result struct, so we can reuse it as the component
                // base address — but we still need the callee's return
                // type name to look up the layout.
                let resolved = resolved.or_else(|| {
                    if let Expr::FunctionCall { callee, args } = &base.node {
                        if let Expr::Name { name } = &callee.node {
                            if let Some(ret_type_name) = callee_return_derived_type_name(st, name) {
                                let base_ptr = lower_expr_full(
                                    b,
                                    locals,
                                    base,
                                    st,
                                    type_layouts,
                                    internal_funcs,
                                    contained_host_refs,
                                    descriptor_params,
                                );
                                return Some((base_ptr, ret_type_name));
                            }
                        }
                        if let Expr::ComponentAccess {
                            base: method_base,
                            component,
                        } = &callee.node
                        {
                            if let Some(tl) = type_layouts {
                                if let Some((_obj_addr, type_name)) =
                                    resolve_component_base_for_method(
                                        b,
                                        locals,
                                        method_base,
                                        st,
                                        tl,
                                    )
                                {
                                    if let Some(layout) = tl.get(&type_name) {
                                        let bp = resolved_bound_proc_for_call(
                                            b,
                                            locals,
                                            st,
                                            layout,
                                            component,
                                            args,
                                            type_layouts,
                                            internal_funcs,
                                            contained_host_refs,
                                            descriptor_params,
                                        )
                                        .or_else(|| layout.bound_proc(component));
                                        if let Some(bp) = bp {
                                            let target_key =
                                                abi_key_for_link_name(st, &bp.target_name)
                                                    .unwrap_or_else(|| bp.abi_name.clone());
                                            if let Some(ret_type_name) =
                                                callee_return_derived_type_name(st, &target_key)
                                            {
                                                let base_ptr = lower_expr_full(
                                                    b,
                                                    locals,
                                                    base,
                                                    st,
                                                    type_layouts,
                                                    internal_funcs,
                                                    contained_host_refs,
                                                    descriptor_params,
                                                );
                                                return Some((base_ptr, ret_type_name));
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    None
                });
                if let Some((base_addr, type_name)) = resolved {
                    if let Some(layout) = tl.get(&type_name) {
                        if let Some(field) = layout.field(component) {
                            let offset = b.const_i64(field.offset as i64);
                            let field_ptr =
                                b.gep(base_addr, vec![offset], IrType::Int(IntWidth::I8));

                            if is_deferred_char_component_field(field) {
                                let (ptr, _len) = load_string_descriptor_view(b, field_ptr);
                                return ptr;
                            }

                            if is_opaque_c_handle_type(&field.type_info) {
                                let ir_ty = type_info_to_ir_type(&field.type_info);
                                return b.load_typed(field_ptr, ir_ty);
                            }

                            if let crate::sema::symtab::TypeInfo::Derived(_) = &field.type_info {
                                if field.pointer {
                                    return b.load_typed(
                                        field_ptr,
                                        IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))),
                                    );
                                }
                                // Non-pointer derived fields stay address-valued
                                // so chained access like x%inner%field can walk
                                // the inline storage directly.
                                return field_ptr;
                            }

                            if field.pointer {
                                let slot_ty =
                                    IrType::Ptr(Box::new(type_info_to_ir_type(&field.type_info)));
                                let pointee = b.load_typed(field_ptr, slot_ty);
                                return b
                                    .load_typed(pointee, type_info_to_ir_type(&field.type_info));
                            }

                            // Character fields: return the pointer to the inline
                            // character data, not a load. The data is stored
                            // inline in the struct, not behind a pointer.
                            if let crate::sema::symtab::TypeInfo::Character { .. } =
                                &field.type_info
                            {
                                return field_ptr;
                            }

                            // Complex fields follow the same address-valued
                            // convention as ordinary complex locals: callers
                            // expect a pointer to the inline [re, im] buffer,
                            // not the aggregate loaded by value. Retag the
                            // byte-addressed field pointer to the real complex
                            // storage type so intrinsic dispatch sees
                            // ptr<[f32/f64 x 2]> instead of ptr<i8>.
                            if let crate::sema::symtab::TypeInfo::Complex { .. } = &field.type_info
                            {
                                let addr = b.ptr_to_int(field_ptr);
                                return b.int_to_ptr(addr, type_info_to_ir_type(&field.type_info));
                            }

                            let ir_ty = type_info_to_ir_type(&field.type_info);
                            return b.load_typed(field_ptr, ir_ty);
                        }
                    } else {
                        eprintln!("warning: no field '{}' in type '{}'", component, type_name);
                    }
                }
            }
            b.const_i32(0) // fallback for unresolved component access
        }

        Expr::ArrayConstructor { values, .. } => {
            // Allocate a temporary stack array, store each literal
            // element into it, return the base pointer. Element
            // type is inferred from the first element's IR type
            // (or defaults to i32 for an empty constructor — rare
            // but legal). Implied-do values are slot-skipped by
            // store_ac_values_into; see the helper for details.
            //
            // The expression form is needed when an array literal
            // appears as a function argument or print item; the
            // assignment form (`a = [1,2,3]`) bypasses this and
            // routes through lower_array_assign for direct stores.
            let first_expr = first_array_constructor_expr(values);
            let first_ti =
                first_array_constructor_type_info(values, Some(locals), st, type_layouts);
            let elem_ty = match first_ti.as_ref() {
                Some(crate::sema::symtab::TypeInfo::Derived(name))
                | Some(crate::sema::symtab::TypeInfo::Class(name)) => type_layouts
                    .and_then(|tl| derived_storage_ir_type(name, tl))
                    .or_else(|| {
                        first_expr.map(|e| {
                            // Peek at the first element's type by lowering
                            // it on a scratch path. Rather than actually
                            // lower (and have to undo), approximate from
                            // the AST: integer literals → i32, real → f64,
                            // etc.
                            infer_const_expr_ty(&e.node, Some(locals), st)
                        })
                    })
                    .unwrap_or(IrType::Int(IntWidth::I32)),
                Some(ti) => type_info_to_ir_type(ti),
                None => first_expr
                    .map(|e| {
                        // Peek at the first element's type by lowering
                        // it on a scratch path. Rather than actually
                        // lower (and have to undo), approximate from
                        // the AST: integer literals → i32, real → f64,
                        // etc.
                        infer_const_expr_ty(&e.node, Some(locals), st)
                    })
                    .unwrap_or(IrType::Int(IntWidth::I32)),
            };
            let n = const_array_constructor_len(values).unwrap_or(values.len() as i64) as u64;
            let arr_ty = IrType::Array(Box::new(elem_ty.clone()), n.max(1));
            let buf = b.alloca(arr_ty);
            let derived_type = first_ti.as_ref().and_then(|ti| match ti {
                crate::sema::symtab::TypeInfo::Derived(name)
                | crate::sema::symtab::TypeInfo::Class(name) => Some(name.as_str()),
                _ => None,
            });
            if derived_type.is_some() {
                let zero32 = b.const_i32(0);
                let total_bytes = b.const_i64(ir_scalar_byte_size(&elem_ty) * n.max(1) as i64);
                b.call(
                    FuncRef::External("memset".into()),
                    vec![buf, zero32, total_bytes],
                    IrType::Ptr(Box::new(IrType::Int(IntWidth::I8))),
                );
            }
            store_ac_values_into(
                b,
                locals,
                buf,
                &elem_ty,
                derived_type,
                values,
                st,
                type_layouts,
                internal_funcs,
                contained_host_refs,
                descriptor_params,
            );
            buf
        }

        Expr::ComplexLiteral { real, imag } => {
            // Complex numbers are stored as a 2-element float array on the stack.
            // Determine float width from the literal parts: if either uses a 'd'/'D'
            // exponent it's double precision (f64), otherwise single (f32).
            let is_double = |e: &crate::ast::expr::SpannedExpr| -> bool {
                if let Expr::RealLiteral { text, .. } = &e.node {
                    text.to_lowercase().contains('d')
                } else {
                    false
                }
            };
            let fw = if is_double(real) || is_double(imag) {
                FloatWidth::F64
            } else {
                FloatWidth::F32
            };
            let elem_ty = IrType::Float(fw);
            let elem_bytes = b.const_i64(if fw == FloatWidth::F64 { 8 } else { 4 });
            let arr_ty = IrType::Array(Box::new(elem_ty.clone()), 2);
            let buf = b.alloca(arr_ty);

            let real_raw = lower_expr_full(
                b,
                locals,
                real,
                st,
                type_layouts,
                internal_funcs,
                contained_host_refs,
                descriptor_params,
            );
            let imag_raw = lower_expr_full(
                b,
                locals,
                imag,
                st,
                type_layouts,
                internal_funcs,
                contained_host_refs,
                descriptor_params,
            );
            let real_val = coerce_to_type(b, real_raw, &elem_ty);
            let imag_val = coerce_to_type(b, imag_raw, &elem_ty);

            // Store real at byte offset 0, imag at byte offset elem_bytes.
            let zero = b.const_i64(0);
            let real_ptr = b.gep(buf, vec![zero], IrType::Int(IntWidth::I8));
            b.store(real_val, real_ptr);
            let imag_ptr = b.gep(buf, vec![elem_bytes], IrType::Int(IntWidth::I8));
            b.store(imag_val, imag_ptr);

            buf
        }
    }
}

/// Approximate the IR type of a constant-or-near-constant
/// expression by inspecting the AST. Used by ArrayConstructor
/// lowering to pick an element type without actually emitting IR.
/// Conservative — falls back to i32 for anything it can't
/// classify.
fn infer_const_expr_ty(
    e: &Expr,
    locals: Option<&HashMap<String, LocalInfo>>,
    st: &SymbolTable,
) -> IrType {
    match e {
        Expr::IntegerLiteral { kind, .. } => {
            let kind_width = kind
                .as_deref()
                .map(|kind_str| int_kind_to_width_in_context(kind_str, locals, None, Some(st)))
                .unwrap_or_else(crate::driver::defaults::default_int_kind);
            IrType::int_from_kind(kind_width)
        }
        Expr::RealLiteral { text, .. } => {
            if text.to_lowercase().contains('d') {
                IrType::Float(FloatWidth::F64)
            } else {
                IrType::Float(FloatWidth::F32)
            }
        }
        Expr::LogicalLiteral { .. } => IrType::Bool,
        Expr::UnaryOp { operand, .. } => infer_const_expr_ty(&operand.node, locals, st),
        Expr::ParenExpr { inner } => infer_const_expr_ty(&inner.node, locals, st),
        _ => IrType::Int(IntWidth::I32),
    }
}

fn lower_structure_constructor_expr(
    b: &mut FuncBuilder,
    locals: &HashMap<String, LocalInfo>,
    type_name: &str,
    args: &[crate::ast::expr::Argument],
    st: &SymbolTable,
    type_layouts: Option<&crate::sema::type_layout::TypeLayoutRegistry>,
    internal_funcs: Option<&HashMap<String, u32>>,
    contained_host_refs: Option<&HashMap<String, Vec<String>>>,
    descriptor_params: Option<&HashMap<String, Vec<bool>>>,
) -> Option<ValueId> {
    let tl = type_layouts?;
    let layout = tl.get(type_name)?;

    let struct_ty = IrType::Array(Box::new(IrType::Int(IntWidth::I8)), layout.size as u64);
    let tmp = b.alloca(struct_ty);
    if derived_layout_needs_runtime_initialization(layout, tl) {
        initialize_derived_storage(b, tmp, layout, tl);
    } else {
        zero_fill_bytes(b, tmp, layout.size as i64);
    }

    let mut positional_idx = 0usize;
    for arg in args {
        let field = if let Some(keyword) = &arg.keyword {
            layout.field(keyword)
        } else {
            let field = layout.fields.get(positional_idx);
            positional_idx += 1;
            field
        };
        let Some(field) = field else {
            eprintln!(
                "warning: structure constructor for '{}' has invalid field initializer",
                type_name
            );
            continue;
        };
        if let crate::ast::expr::SectionSubscript::Element(e) = &arg.value {
            let offset = b.const_i64(field.offset as i64);
            let field_ptr = b.gep(tmp, vec![offset], IrType::Int(IntWidth::I8));
            store_derived_field_expr(
                b,
                locals,
                field_ptr,
                field,
                e,
                st,
                tl,
                internal_funcs,
                contained_host_refs,
                descriptor_params,
            );
        }
    }

    Some(tmp)
}

fn fortran_type_to_ir_scalar_type(ft: &crate::sema::types::FortranType) -> Option<IrType> {
    use crate::sema::types::FortranType;
    match ft {
        FortranType::Integer { kind } => match kind {
            1 => Some(IrType::Int(IntWidth::I8)),
            2 => Some(IrType::Int(IntWidth::I16)),
            4 => Some(IrType::Int(IntWidth::I32)),
            8 => Some(IrType::Int(IntWidth::I64)),
            16 => Some(IrType::Int(IntWidth::I128)),
            _ => None,
        },
        FortranType::Real { kind } => match kind {
            4 => Some(IrType::Float(FloatWidth::F32)),
            8 => Some(IrType::Float(FloatWidth::F64)),
            _ => None,
        },
        FortranType::Complex { kind } => match kind {
            8 => Some(IrType::Array(Box::new(IrType::Float(FloatWidth::F64)), 2)),
            _ => Some(IrType::Array(Box::new(IrType::Float(FloatWidth::F32)), 2)),
        },
        FortranType::Logical { kind } => match kind {
            1 => Some(IrType::Int(IntWidth::I8)),
            2 => Some(IrType::Int(IntWidth::I16)),
            4 => Some(IrType::Bool),
            8 => Some(IrType::Int(IntWidth::I64)),
            _ => None,
        },
        FortranType::Derived { .. } => Some(IrType::Ptr(Box::new(IrType::Int(IntWidth::I8)))),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::super::printer;
    use super::super::verify;
    use super::*;
    use crate::lexer::Lexer;
    use crate::parser::Parser;
    use crate::sema::resolve;

    fn lower_source(src: &str) -> Module {
        let tokens = Lexer::tokenize(src, 0).unwrap();
        let mut parser = Parser::new(&tokens);
        let units = parser.parse_file().unwrap();
        let (st, layouts) = {
            let rr = resolve::resolve_file(&units, &[]).unwrap();
            (rr.st, rr.type_layouts)
        };
        lower_file(
            &units,
            &st,
            &layouts,
            HashMap::new(),
            HashMap::new(),
            HashMap::new(),
            HashMap::new(),
        )
        .0
    }

    fn lower_and_verify(src: &str) -> (Module, String) {
        let module = lower_source(src);
        let errs = verify::verify_module(&module);
        assert!(
            errs.is_empty(),
            "IR verification failed:\n{}\nIR:\n{}",
            errs.iter()
                .map(|e| e.to_string())
                .collect::<Vec<_>>()
                .join("\n"),
            printer::print_module(&module)
        );
        let ir_text = printer::print_module(&module);
        (module, ir_text)
    }

    #[test]
    fn lower_integer_arithmetic() {
        let (module, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: x, y, z
  x = 10
  y = 20
  z = x + y
end program
",
        );
        assert_eq!(module.functions.len(), 1);
        assert!(ir.contains("const_int 10"));
        assert!(ir.contains("const_int 20"));
        assert!(ir.contains("iadd"));
    }

    #[test]
    fn select_type_pointer_result_component_assignment_verifies() {
        lower_and_verify(
            "\
module m
  implicit none
  type :: base_t
  end type base_t
  type, extends(base_t) :: float_box
    real(8) :: raw = 0.0d0
  end type float_box
contains
  function cast_float(val) result(ptr)
    class(base_t), intent(in), target :: val
    real(8), pointer :: ptr
    select type (val)
    type is (float_box)
      ptr => val%raw
    class default
      nullify(ptr)
    end select
  end function cast_float
end module m
",
        );
    }

    #[test]
    fn lower_real_arithmetic() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  real :: a, b, c
  a = 3.14
  b = 2.0
  c = a * b
end program
",
        );
        assert!(ir.contains("const_float"));
        assert!(ir.contains("fmul"));
    }

    #[test]
    fn lower_print() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: x
  x = 42
  print *, x
end program
",
        );
        assert!(ir.contains("afs_write_int"));
        assert!(ir.contains("afs_write_newline"));
    }

    #[test]
    fn lower_print_integer16_uses_wide_writer() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer(16) :: x
  x = 170141183460469231731687303715884105727_16
  print *, x
end program
",
        );
        assert!(ir.contains("afs_write_int128"));
    }

    #[test]
    fn lower_read_integer16_uses_wide_reader() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer(16) :: x
  read(*, *) x
end program
",
        );
        assert!(ir.contains("afs_read_int128"));
    }

    #[test]
    fn lower_internal_write_integer16_uses_wide_buffer_writer() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  character(len=96) :: buf
  integer(16) :: x
  x = 170141183460469231731687303715884105727_16
  write(buf, *) x
end program
",
        );
        assert!(ir.contains("afs_write_internal_int128"));
    }

    #[test]
    fn lower_internal_read_integer16_uses_wide_buffer_reader() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  character(len=96) :: buf
  integer(16) :: x
  read(buf, *) x
end program
",
        );
        assert!(ir.contains("afs_read_internal_int128"));
    }

    #[test]
    fn lower_formatted_internal_write_integer16_uses_internal_format_sink() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  character(len=96) :: buf
  integer(16) :: x
  x = 170141183460469231731687303715884105727_16
  write(buf, '(I40)') x
end program
",
        );
        assert!(ir.contains("afs_fmt_begin_internal"));
        assert!(ir.contains("afs_fmt_push_int128"));
    }

    #[test]
    fn lower_formatted_internal_read_integer16_uses_internal_format_reader() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  character(len=64) :: buf
  integer(16) :: x
  read(buf, '(I40)') x
end program
",
        );
        assert!(ir.contains("afs_fmt_read_int128_internal"));
    }

    #[test]
    fn lower_formatted_read_integer16_uses_wide_format_reader() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer(16) :: x
  read(10, '(I40)') x
end program
",
        );
        assert!(ir.contains("afs_fmt_read_int128"));
    }

    #[test]
    fn lower_formatted_write_integer16_uses_wide_push() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer(16) :: x
  x = 170141183460469231731687303715884105727_16
  write(*, '(I40)') x
end program
",
        );
        assert!(ir.contains("afs_fmt_push_int128"));
    }

    #[test]
    fn lower_unary_minus() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: x, y
  x = 5
  y = -x
end program
",
        );
        assert!(ir.contains("ineg"));
    }

    #[test]
    fn vector_subscripted_component_assign_does_not_poison_following_array_use() {
        let _ = lower_and_verify(
            "\
module m
  implicit none
  type :: toml_label
    integer :: first
  end type
  type :: line_token
    integer :: first, last
  end type
contains
  pure function line_tokens(input) result(token)
    character(len=*), intent(in) :: input
    type(line_token), allocatable :: token(:)
    allocate(token(2))
    token = [line_token(1, 1), line_token(2, len(input))]
  end function

  pure function f(input, label) result(first)
    character(len=*), intent(in) :: input
    type(toml_label), intent(in) :: label(:)
    integer :: first
    integer :: line(size(label))
    integer :: shift(size(label))
    type(line_token), allocatable :: token(:)
    integer :: it

    allocate(token(0))
    token = line_tokens(input)
    line(:) = [(count(token%first <= label(it)%first), it = 1, size(label))]
    shift(:) = token(line)%first
    first = line(1)
  end function
end module
",
        );
    }

    #[test]
    fn lower_multiple_vars() {
        let (module, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: a, b, c, d
  a = 1
  b = 2
  c = 3
  d = a + b + c
end program
",
        );
        assert_eq!(module.functions.len(), 1);
        // Should have two iadd operations (a+b, then result+c).
        let iadd_count = ir.matches("iadd").count();
        assert_eq!(iadd_count, 2);
    }

    #[test]
    fn lower_stop() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  stop
end program
",
        );
        assert!(ir.contains("rt_call @__afs_stop"));
        assert!(ir.contains("unreachable"));
    }

    #[test]
    fn ir_passes_verifier() {
        lower_and_verify("program p\n  implicit none\n  integer :: x\n  x = 1\nend program\n");
        lower_and_verify("program p\n  implicit none\n  real :: x\n  x = 1.0\nend program\n");
        lower_and_verify("program p\n  implicit none\n  integer :: x, y\n  x = 1\n  y = x + 2\n  print *, y\nend program\n");
    }

    // ---- Control flow ----

    #[test]
    fn lower_if_then_else() {
        // Simple diamond `if (cond) y = a; else y = b` lowers to Select.
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: x, y
  x = 5
  if (x > 0) then
    y = 1
  else
    y = -1
  end if
end program
",
        );
        assert!(
            ir.contains("select"),
            "simple diamond should lower to select: {}",
            ir
        );
    }

    #[test]
    fn lower_if_then_else_branching() {
        // Non-diamond IF/ELSE (multi-statement body) must still use branches.
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: x, y, z
  x = 5
  if (x > 0) then
    y = 1
    z = 2
  else
    y = -1
    z = -2
  end if
end program
",
        );
        assert!(
            ir.contains("cond_br"),
            "multi-stmt if/else should use branches: {}",
            ir
        );
        assert!(ir.contains("if_then"));
        assert!(ir.contains("if_else"));
        assert!(ir.contains("if_end"));
    }

    #[test]
    fn lower_if_then_else_by_ref_dummy_uses_branches() {
        let (_, ir) = lower_and_verify(
            "\
module m
contains
  subroutine set_flag(flag)
    integer, intent(out) :: flag
    if (.true.) then
      flag = 7
    else
      flag = -1
    end if
  end subroutine
end module
",
        );
        assert!(
            !ir.contains("select"),
            "by-ref dummy assignments must not use the select fast path: {}",
            ir
        );
        assert!(
            ir.contains("cond_br"),
            "by-ref dummy assignments should lower through ordinary control flow: {}",
            ir
        );
    }

    #[test]
    fn lower_if_elseif() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: x, y
  x = 5
  if (x > 10) then
    y = 1
  else if (x > 0) then
    y = 2
  else
    y = 3
  end if
end program
",
        );
        assert!(ir.contains("elseif_0_then"));
    }

    #[test]
    fn lower_if_stmt() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: x
  x = 5
  if (x > 0) x = 0
end program
",
        );
        assert!(ir.contains("if_then"));
        assert!(ir.contains("if_end"));
    }

    #[test]
    fn lower_do_loop() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: i, s
  s = 0
  do i = 1, 10
    s = s + i
  end do
end program
",
        );
        assert!(ir.contains("do_check"));
        assert!(ir.contains("do_body"));
        assert!(ir.contains("do_incr"));
        assert!(ir.contains("do_exit"));
        assert!(ir.contains("icmp le"));
    }

    #[test]
    fn lower_do_loop_with_step() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: i, s
  s = 0
  do i = 1, 10, 2
    s = s + i
  end do
end program
",
        );
        assert!(ir.contains("const_int 2"));
        assert!(ir.contains("do_incr"));
    }

    #[test]
    fn lower_do_concurrent_uses_distinct_blocks() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: i, arr(10)
  do concurrent (i = 1:10)
    arr(i) = i * 2
  end do
end program
",
        );
        assert!(ir.contains("doconc_check"));
        assert!(ir.contains("doconc_body"));
        assert!(ir.contains("doconc_incr"));
        assert!(ir.contains("doconc_exit"));
        assert!(ir.contains("icmp le"));
    }

    #[test]
    fn lower_do_concurrent_mask_emits_guard() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: i, arr(6)
  arr = 0
  do concurrent (i = 1:6, mod(i, 2) == 0)
    arr(i) = i
  end do
end program
",
        );
        assert!(ir.contains("doconc_check"));
        assert!(ir.contains("if_then"));
        assert!(ir.contains("if_end"));
    }

    #[test]
    fn mod_intrinsic_coerces_mixed_width_integer_args() {
        let (_, ir) = lower_and_verify(
            "\
program test
  use iso_fortran_env, only: int64
  implicit none
  integer(int64) :: total_commands
  logical :: should_report
  total_commands = 51_int64
  should_report = mod(total_commands, 50_int64) == 0_int64
end program
",
        );
        assert!(ir.contains("imod"));
        assert!(!ir.contains("operand width mismatch"));
    }

    #[test]
    fn lower_do_concurrent_multiple_controls_nests_loops() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: i, j, arr(3, 2)
  do concurrent (i = 1:3, j = 1:2)
    arr(i, j) = i * 10 + j
  end do
end program
",
        );
        assert!(ir.matches("doconc_check").count() >= 2);
    }

    #[test]
    fn lower_do_concurrent_full_array_map_uses_bulk_kernel() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: i, a(8), b(8), c(8)
  do i = 1, 8
    a(i) = i
    b(i) = i * 10
  end do
  do concurrent (i = 1:8)
    c(i) = a(i) + b(i)
  end do
end program
",
        );
        assert!(ir.contains("call @afs_array_add_i32("));
        assert!(!ir.contains("doconc_check"));
    }

    #[test]
    fn lower_whole_array_elemental_assign_uses_do_concurrent_shape() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: a(4), b(4), i
  do i = 1, 4
    a(i) = i * 2
  end do
  b = shift_scale(a, 5)
contains
  elemental function shift_scale(x, y) result(r)
    integer, intent(in) :: x, y
    integer :: r
    r = x * 2 + y
  end function
end program
",
        );
        assert!(ir.contains("doconc_check"));
        assert!(ir.contains("call @afs_internal___prog_test_1("));
    }

    #[test]
    fn lower_do_while() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: x
  x = 10
  do while (x > 0)
    x = x - 1
  end do
end program
",
        );
        assert!(ir.contains("do_while_header"));
        assert!(ir.contains("do_while_body"));
        assert!(ir.contains("do_while_exit"));
    }

    #[test]
    fn lower_exit_cycle() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: i, s
  s = 0
  do i = 1, 100
    if (i > 10) exit
    if (i == 5) cycle
    s = s + i
  end do
end program
",
        );
        // EXIT should branch to do_exit, CYCLE to do_incr.
        assert!(ir.contains("do_exit"));
        assert!(ir.contains("do_incr"));
    }

    #[test]
    fn lower_select_case() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: x, y
  x = 2
  select case (x)
  case (1)
    y = 10
  case (2)
    y = 20
  case default
    y = 0
  end select
end program
",
        );
        assert!(ir.contains("case_0_body"));
        assert!(ir.contains("case_1_body"));
        assert!(ir.contains("select_end"));
    }

    #[test]
    fn lower_nested_loops() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: i, j, s
  s = 0
  do i = 1, 10
    do j = 1, 10
      s = s + i * j
    end do
  end do
end program
",
        );
        // Two loops means 2 blocks named "do_check_N":
        let label_count = ir.matches("do_check_").count();
        assert!(
            label_count >= 2,
            "expected at least 2 loop headers, got {} in:\n{}",
            label_count,
            ir
        );
    }

    #[test]
    fn lower_do_negative_step() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: i, s
  s = 0
  do i = 10, 1, -1
    s = s + i
  end do
end program
",
        );
        // Negative step should use >= comparison, not <=.
        assert!(
            ir.contains("icmp ge"),
            "expected 'icmp ge' for negative step in:\n{}",
            ir
        );
    }

    #[test]
    fn lower_function_return() {
        let (_, ir) = lower_and_verify(
            "\
function square(x) result(y)
  integer, intent(in) :: x
  integer :: y
  y = x * x
  return
end function
",
        );
        // RETURN should load the result variable and ret it, not ret void.
        assert!(ir.contains("ret %"), "expected 'ret %value' in:\n{}", ir);
        assert!(
            !ir.contains("ret void"),
            "function should not ret void in:\n{}",
            ir
        );
    }

    #[test]
    fn lower_return() {
        let (_, ir) = lower_and_verify(
            "\
subroutine foo()
  implicit none
  return
end subroutine
",
        );
        assert!(ir.contains("ret void"));
    }

    #[test]
    fn lower_infinite_do_function_with_return() {
        let (_, ir) = lower_and_verify(
            "\
logical function wait_min7() result(success)
  do
    success = .false.
    return
  end do
end function wait_min7
",
        );
        assert!(ir.contains("ret %"), "expected function return in:\n{}", ir);
        assert!(
            !ir.contains("do_exit"),
            "unreachable do-exit block should be pruned in:\n{}",
            ir
        );
    }

    #[test]
    fn lower_associate() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: x
  x = 42
  associate (n => x)
    print *, n
  end associate
end program
",
        );
        assert!(ir.contains("afs_write_int"));
    }

    // ---- Allocatable / strings ----

    #[test]
    fn lower_allocate_deallocate() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  real, allocatable :: a(:)
  allocate(a(100))
  deallocate(a)
end program
",
        );
        assert!(
            ir.contains("call @afs_allocate_array"),
            "expected allocate call in:\n{}",
            ir
        );
        assert!(
            ir.contains("call @afs_deallocate_array"),
            "expected deallocate call in:\n{}",
            ir
        );
    }

    #[test]
    fn lower_implicit_dealloc_at_scope_exit() {
        let (_, ir) = lower_and_verify(
            "\
subroutine foo()
  implicit none
  real, allocatable :: temp(:)
  allocate(temp(10))
end subroutine
",
        );
        // Should have implicit deallocation before ret.
        let dealloc_count = ir.matches("call @afs_deallocate_array").count();
        assert!(
            dealloc_count >= 1,
            "expected implicit deallocation, got {} in:\n{}",
            dealloc_count,
            ir
        );
    }

    #[test]
    fn lower_allocatable_c_char_array_element_assignment() {
        let (_, ir) = lower_and_verify(
            "\
subroutine foo(str, n)
  use iso_c_binding, only: c_char
  implicit none
  character(len=*), intent(in) :: str
  integer, intent(in) :: n
  character(kind=c_char), target, allocatable :: c_str(:)
  integer :: i
  allocate(c_str(n + 1))
  do i = 1, n
    c_str(i) = str(i:i)
  end do
  c_str(n + 1) = char(10)
end subroutine
",
        );
        assert!(
            ir.contains("call @afs_allocate_array"),
            "expected descriptor-backed allocation in:\n{}",
            ir
        );
    }

    #[test]
    fn lower_runtime_bound_explicit_shape_local_uses_descriptor_storage() {
        let (_, ir) = lower_and_verify(
            "\
subroutine foo(n)
  implicit none
  integer, intent(in) :: n
  integer :: argv(n + 1)
  argv(n + 1) = 22
end subroutine
",
        );
        assert!(
            ir.contains("call @afs_allocate_array"),
            "expected runtime-bound local array allocation in:\n{}",
            ir
        );
        assert!(
            ir.contains("call @afs_deallocate_array"),
            "expected runtime-bound local array cleanup in:\n{}",
            ir
        );
    }

    #[test]
    fn lower_string_literal() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  print *, 'hello'
end program
",
        );
        assert!(
            ir.contains("const_string"),
            "expected string constant in:\n{}",
            ir
        );
        assert!(ir.contains("afs_write_string"));
    }

    // ---- Calls ----

    #[test]
    fn lower_call_passes_addresses() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: x
  x = 42
  call foo(x)
end program
",
        );
        // x should be passed by reference — the alloca address, not a loaded value.
        // The call should reference the alloca directly.
        assert!(ir.contains("call @foo("));
    }

    #[test]
    fn lower_call_expression_arg() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: x
  x = 5
  call foo(x + 1)
end program
",
        );
        // Expression arg: x+1 evaluated, stored to temp, temp address passed.
        assert!(ir.contains("iadd"));
        assert!(ir.contains("alloca")); // temp for expression result
        assert!(ir.contains("call @foo("));
    }

    // ---- Arrays ----

    #[test]
    fn lower_array_declaration() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: a(10)
  a(1) = 42
end program
",
        );
        // Should alloca an array of 10 i32, then GEP + store.
        assert!(
            ir.contains("[i32 x 10]"),
            "expected array alloca in:\n{}",
            ir
        );
        assert!(ir.contains("gep"), "expected GEP in:\n{}", ir);
    }

    #[test]
    fn lower_array_read() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: a(10), x
  a(3) = 99
  x = a(3)
end program
",
        );
        // Reading array element: GEP + load.
        let gep_count = ir.matches("gep").count();
        assert!(
            gep_count >= 2,
            "expected at least 2 GEPs (write + read), got {} in:\n{}",
            gep_count,
            ir
        );
    }

    #[test]
    fn lower_2d_array() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: mat(3, 4)
  mat(2, 3) = 42
end program
",
        );
        // 2D array: alloca [i32 x 12], column-major offset.
        assert!(
            ir.contains("[i32 x 12]"),
            "expected 3*4=12 element array in:\n{}",
            ir
        );
        assert!(ir.contains("gep"), "expected GEP in:\n{}", ir);
    }

    #[test]
    fn lower_array_in_loop() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: a(10), i
  do i = 1, 10
    a(i) = i * 2
  end do
end program
",
        );
        assert!(ir.contains("gep"));
        assert!(ir.contains("imul"));
    }

    #[test]
    fn lower_module_globals() {
        let module = lower_source(
            "\
module mymod
  implicit none
  integer :: counter
  real :: threshold
end module
",
        );
        assert_eq!(module.globals.len(), 2);
        assert!(module.globals.iter().any(|g| g.name.contains("counter")));
        assert!(module.globals.iter().any(|g| g.name.contains("threshold")));
    }

    #[test]
    fn lower_block_construct() {
        let (_, ir) = lower_and_verify(
            "\
program test
  implicit none
  integer :: x
  x = 1
  block
    x = x + 1
  end block
end program
",
        );
        assert!(ir.contains("iadd"));
    }
}
